                if (codes == null) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid totp code", code = "TOTP_INVALID"))
                }
                call.respond(TotpStatusResponse(enabled = true, backupCodes = codes))
            }

