            // ─── 高级搜索 API（按类型/日期/聊天范围过滤）──────
            post("/api/search") {
                val userId = call.principal<JWTPrincipal>()?.payload?.subject
                if (userId == null) { call.respond(HttpStatusCode.Unauthorized, ErrorResponse("未认证")); return@post }
                // 每用户限流：底层 LIKE 全表扫描成本高，防止搜索 DoS
                if (!globalSearchRateLimiter.acquire(userId, maxPerMinute = 10)) {
                    return@post call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("搜索太频繁，请稍后再试"))
                }
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid json"))
                val query = obj["query"]?.jsonPrimitive?.content.orEmpty()
                // 最小查询长度 2：单字符 LIKE '%x%' 无检索价值却触发全表扫描
                if (query.length < 2 || query.length > 200) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("查询条件无效"))
                }
                val filterType = obj["type"]?.jsonPrimitive?.content.orEmpty() // "ALL" | "TEXT" | "IMAGE" | "FILE" | "VOICE" | "VIDEO" | "LINK"
                val dateFrom = obj["dateFrom"]?.jsonPrimitive?.longOrNull ?: 0L
                val dateTo = obj["dateTo"]?.jsonPrimitive?.longOrNull ?: 0L
                val chatId = obj["chatId"]?.jsonPrimitive?.content.orEmpty()
                val limit = (obj["limit"]?.jsonPrimitive?.intOrNull ?: 50).coerceIn(1, 200)

                // 使用现有 MessageRepository 进行搜索
                val results = messageRepo.globalSearch(
                    userId = userId,
                    query = query,
                    filterType = filterType,
                    dateFrom = dateFrom,
                    dateTo = dateTo,
                    chatId = chatId,
                    limit = limit
                )
                call.respond(
                buildJsonObject {
put("ok", true)
put("results", Json.parseToJsonElement(Json.encodeToString(results)))
                }
            )
            }
            suspend fun notifyFriendRequest(request: FriendRequestResponse, action: String) {
                val payload = json.encodeToString(
                    FriendRequestEventPayload.serializer(),
                    FriendRequestEventPayload(action = action, request = request)
                )
                val envelope = json.encodeToString(WsMessage.serializer(), WsMessage("FRIEND_REQUEST", payload))
                val peers = setOf(request.fromUser.id, request.toUser.id)
                peers.forEach { pid ->
                    // 9.129：WS 实时事件与 push 同口径——申请创建后若双方已互相拉黑，
                    // 不再向对方实时推送好友申请事件（push 路径早已过滤，WS 漏网）
                    val other = if (pid == request.fromUser.id) request.toUser.id else request.fromUser.id
                    if (userRepo.isBlockedEitherWay(pid, other)) return@forEach
                    sendToUser(pid, envelope)
                }
                // FCM wake for offline peer (CREATED → recipient; ACCEPTED → original sender)
                when (action) {
                    "CREATED" -> if (!userRepo.isBlockedEitherWay(request.toUser.id, request.fromUser.id)) {
                        pushService.enqueueFriendRequest(
                            recipientId = request.toUser.id,
                            fromUserId = request.fromUser.id,
                            requestId = request.id,
                            action = action
                        )
                    }
                    "ACCEPTED" -> if (!userRepo.isBlockedEitherWay(request.fromUser.id, request.toUser.id)) {
                        pushService.enqueueFriendRequest(
                            recipientId = request.fromUser.id,
                            fromUserId = request.toUser.id,
                            requestId = request.id,
                            action = action
                        )
                    }
                }
            }

            post("/api/friends/requests") {
                if (!com.maodouchat.server.service.RuntimeConfigService.isFriendRequestsEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("friend_requests_disabled"))
                    return@post
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfSuspended(userRepo, userId)) return@post
                if (!friendRequestRateLimiter.acquire(userId, maxPerMinute = 10)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@post
                }
                val req = call.receiveBoundedText()?.let { parseJson<SendFriendRequestBody>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@post
                }
                val toUserId = req.toUserId.trim()
                if (toUserId.isBlank()) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("目标用户无效"))
                    return@post
                }
                when (val result = friendRepo.sendRequest(userId, toUserId, req.message)) {
                    is FriendRepository.Result.Success -> {
                        notifyFriendRequest(result.request, "CREATED")
                        call.respond(HttpStatusCode.Created, result.request)
                    }
                    is FriendRepository.Result.Failure -> {
                        val status = when (result.code) {
                            "USER_NOT_FOUND" -> HttpStatusCode.NotFound
                            "BLOCKED", "SELF" -> HttpStatusCode.Forbidden
                            "ALREADY_FRIENDS", "ALREADY_PENDING", "INCOMING_PENDING" -> HttpStatusCode.Conflict
                            else -> HttpStatusCode.BadRequest
                        }
                        call.respond(status, ErrorResponse(result.message, code = result.code))
                    }
                }
            }

            get("/api/friends/requests/incoming") {
