            post("/api/friends/requests/{id}/accept") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                // 8.40：封禁用户不得接受好友（与 send 侧一致，防被封禁仍触发 WS/FCM fanout）
                if (call.rejectIfSuspended(userRepo, userId)) return@post
                val id = call.parameters["id"].orEmpty()
                when (val result = friendRepo.acceptRequest(userId, id)) {
                    is FriendRepository.Result.Success -> {
                        notifyFriendRequest(result.request, "ACCEPTED")
                        call.respond(result.request)
                    }
                    is FriendRepository.Result.Failure -> {
                        val status = when (result.code) {
                            "NOT_FOUND" -> HttpStatusCode.NotFound
                            "FORBIDDEN" -> HttpStatusCode.Forbidden
                            else -> HttpStatusCode.BadRequest
                        }
                        call.respond(status, ErrorResponse(result.message, code = result.code))
                    }
                }
            }

            post("/api/friends/requests/{id}/reject") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfSuspended(userRepo, userId)) return@post
                val id = call.parameters["id"].orEmpty()
                when (val result = friendRepo.rejectRequest(userId, id)) {
                    is FriendRepository.Result.Success -> {
                        notifyFriendRequest(result.request, "REJECTED")
                        call.respond(result.request)
