                    if (!isMember) return@get call.respond(HttpStatusCode.NotFound, ErrorResponse("member not found"))
                    call.respond(
                buildJsonObject {
put("userId", userId)
put("status", "member")
put("role", "MEMBER")
                }
            )
                } else {
                    call.respond(
                buildJsonObject {
put("userId", m.userId)
put("name", m.name)
put("role", m.role)
put("title", (m.title ?: ""))
put("mutedUntil", m.mutedUntil)
put("status", if (m.mutedUntil > System.currentTimeMillis()) "restricted" else "member")
                }
            )
