            post("/api/bot/restrictChatMember") {
                val headerToken = call.request.headers["X-Bot-Token"].orEmpty()
                val bearer = call.request.headers["Authorization"].bearerTokenOrNull().orEmpty()
                val token = headerToken.ifBlank { bearer }
                val bot = com.maodouchat.server.repository.BotRepository.authenticate(token)
                    ?: return@post call.respond(HttpStatusCode.Unauthorized, ErrorResponse("invalid bot token"))
                // 每 bot 限流：防单 bot 高频 fanout（WS + FCM 风暴）
                if (!botSendRateLimiter.acquire(bot.id, maxPerMinute = 60)) {
                    return@post call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作太频繁，请稍后再试"))
                }
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid json"))
                val chatId = obj["chatId"]?.jsonPrimitive?.content.orEmpty()
                val userId = obj["userId"]?.jsonPrimitive?.content.orEmpty()
                var until = obj["untilDate"]?.jsonPrimitive?.content?.toLongOrNull()
                    ?: obj["mutedUntil"]?.jsonPrimitive?.content?.toLongOrNull()
                    ?: 0L
                if (chatId.isBlank() || userId.isBlank()) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("chatId/userId required"))
                }
                // 8.33 修复：与用户端 mute 路由一致，禁言时长上限 30 天（此前 bot 可无限期禁言）
                val nowMs = System.currentTimeMillis()
                if (until > 0L) {
                    if (until <= nowMs) until = 0L
                    else if (until > nowMs + MAX_MUTE_DURATION_MS) until = nowMs + MAX_MUTE_DURATION_MS
                }
                if (!chatRepo.isParticipant(chatId, bot.id)) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("bot not in chat"))
                }
                // Promote bot role temporarily for mute: treat bot as ADMIN if owner invited as member
                // Use owner path: if bot role is MEMBER, still try mute only when bot is elevated — promote on invite.
                val mutation = chatRepo.updateGroupMemberMuteAsAdmin(
                    chatId = chatId,
                    actorId = bot.id,
                    targetUserId = userId,
                    mutedUntil = until,
                    requireBotDeliverable = true
                )
                com.maodouchat.server.repository.BotRepository.logCommand(bot.id, chatId, userId, "restrictChatMember")
                if (mutation != com.maodouchat.server.repository.ChatRepository.GroupMemberMutationResult.UPDATED) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("restrict failed: $mutation"))
                }
                notifyGroupRevisionChanged(chatRepo, json, chatId, "MEMBER_MUTED", bot.id, userId)
                call.respond(
                buildJsonObject {
put("ok", true)
put("userId", userId)
put("mutedUntil", until)
                }
            )
            }

