                if (!ok) return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("copy failed"))
                com.maodouchat.server.repository.BotRepository.logCommand(bot.id, toChatId, messageId, "copyMessage")
                val botMessage = com.maodouchat.server.model.MessageResponse(
                    id = newId, chatId = toChatId, senderId = bot.id, content = content,
                    type = if (t == "MARKDOWN") "MARKDOWN" else "TEXT", timestamp = now, status = "SENT"
                )
                val participantIds = try {
                    org.jetbrains.exposed.sql.transactions.transaction {
                        com.maodouchat.server.db.ChatParticipants.selectAll()
                            .where { com.maodouchat.server.db.ChatParticipants.chatId eq toChatId }
                            .map { it[com.maodouchat.server.db.ChatParticipants.userId] }
                    }
                } catch (_: Exception) { emptyList() }
                if (participantIds.isNotEmpty()) {
                    val msgJson = json.encodeToString(WsMessage("NEW_MESSAGE", json.encodeToString(botMessage)))
                    val botBlockedIds = try {
                        userRepo.blockedEitherWayIdsInTx(bot.id, participantIds)
                    } catch (_: Exception) { emptySet() }
                    val sourceBlockedIds = try {
                        userRepo.blockedEitherWayIdsInTx(src.senderId, participantIds)
                    } catch (_: Exception) { emptySet() }
                    for (pid in participantIds) {
                        // 被拉黑 bot 的接收方跳过；转发/复制的是原作者内容，被拉黑原作者的接收方也跳过（防绕过拉黑）
                        if (pid in botBlockedIds || pid in sourceBlockedIds) continue
                        try { sendToUser(pid, msgJson) } catch (e: CancellationException) { throw e } catch (_: Exception) { }
                    }
                }
                call.respond(
                buildJsonObject {
put("ok", true)
put("messageId", newId)
put("fromChatId", fromChatId)
put("chatId", toChatId)
                }
            )
            }

            post("/api/bot/leaveChat") {
                val headerToken = call.request.headers["X-Bot-Token"].orEmpty()
                val bearer = call.request.headers["Authorization"].bearerTokenOrNull().orEmpty()
                val token = headerToken.ifBlank { bearer }
                val bot = com.maodouchat.server.repository.BotRepository.authenticate(token)
                    ?: return@post call.respond(HttpStatusCode.Unauthorized, ErrorResponse("invalid bot token"))
                // 每 bot 限流：防单 bot 高频 fanout（WS + FCM 风暴）
                if (!botSendRateLimiter.acquire(bot.id, maxPerMinute = 60)) {
                    return@post call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作太频繁，请稍后再试"))
                }
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid json"))
                val chatId = obj["chatId"]?.jsonPrimitive?.content.orEmpty()
                if (chatId.isBlank()) return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("chatId required"))
                // 8.33 修复：与用户退群一致——退群前抓取成员，成功后广播 memberRevision；群主 bot 退群返回 409
                val wasGroup = chatRepo.getChatById(chatId)?.isGroup == true
                val recipientsBefore = if (wasGroup) chatRepo.getParticipantIds(chatId) else emptyList()
                val outcome = runCatching {
                    chatRepo.leaveChat(chatId = chatId, userId = bot.id, requireBotDeliverable = true)
                }.getOrNull()
                com.maodouchat.server.repository.BotRepository.logCommand(bot.id, chatId, null, "leaveChat")
                if (outcome?.result == ChatRepository.LeaveChatResult.OWNER_TRANSFER_REQUIRED) {
                    return@post call.respond(
                        HttpStatusCode.Conflict,
                        ErrorResponse("群主需先转让群主身份再退出群聊", code = "GROUP_OWNER_TRANSFER_REQUIRED")
                    )
                }
                if (wasGroup && outcome?.result == ChatRepository.LeaveChatResult.LEFT) {
                    notifyGroupRevisionChanged(
                        chatRepo = chatRepo,
                        json = json,
                        chatId = chatId,
                        reason = "MEMBER_LEFT",
                        actorId = bot.id,
                        targetUserId = bot.id,
                        recipientIds = recipientsBefore
                    )
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
put("chatId", chatId)
put("result", (outcome?.result?.name ?: "UNKNOWN"))
                }
            )
            }

