                }
                notifyGroupRevisionChanged(
                    chatRepo = chatRepo,
                    json = json,
                    chatId = chatId,
                    reason = "MEMBER_REMOVED",
                    actorId = bot.id,
                    targetUserId = userId,
                    recipientIds = recipientsBefore
                )
                call.respond(
