                    ?: return@post call.respond(HttpStatusCode.Unauthorized, ErrorResponse("invalid bot token"))
                // 每 bot 限流：防单 bot 高频 fanout（WS + FCM 风暴）
                if (!botSendRateLimiter.acquire(bot.id, maxPerMinute = 60)) {
                    return@post call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作太频繁，请稍后再试"))
                }
                if (!com.maodouchat.server.service.RuntimeConfigService.isMarkdownEnabled()) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("markdown disabled by admin"))
                }
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid json"))
                val chatId = obj["chatId"]?.jsonPrimitive?.content.orEmpty()
                val code = (obj["code"] ?: obj["text"])?.jsonPrimitive?.content.orEmpty().take(3500)
                val lang = obj["language"]?.jsonPrimitive?.content.orEmpty().take(24)
                if (chatId.isBlank() || code.isBlank()) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("chatId/code required"))
                }
                if (!chatRepo.isParticipant(chatId, bot.id)) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("bot not in chat"))
                }
                val fenced = if (lang.isNotBlank()) "```$lang\n$code\n```" else "```\n$code\n```"
                val msgId = "bot_" + java.util.UUID.randomUUID().toString().replace("-", "").take(16)
                val now = System.currentTimeMillis()
                val ok = runCatching {
                    messageRepo.insertBotMessage(msgId, chatId, bot.id, fenced, now, "MARKDOWN")
                }.getOrDefault(false)
                if (!ok) return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("send failed"))
                com.maodouchat.server.repository.BotRepository.logCommand(bot.id, chatId, null, "sendCode")
                val botMessage = com.maodouchat.server.model.MessageResponse(
                    id = msgId, chatId = chatId, senderId = bot.id, content = fenced,
                    type = "MARKDOWN", timestamp = now, status = "SENT"
                )
                val participants = chatRepo.getParticipantIds(chatId)
                val botBlockedIds = try {
                    userRepo.blockedEitherWayIdsInTx(bot.id, participants)
                } catch (_: Exception) { emptySet() }
                participants.forEach { pid ->
                    // 8.33 修复：与 sendMessage 一致，拉黑 bot 的用户不应收到 bot 的 WS 消息
                    if (pid in botBlockedIds) return@forEach
                    try {
                        sendToUser(pid, json.encodeToString(WsMessage("NEW_MESSAGE", json.encodeToString(botMessage))))
                    } catch (e: CancellationException) { throw e } catch (_: Exception) { }
                }
                call.respond(
                buildJsonObject {
put("ok", true)
put("messageId", msgId)
put("type", "MARKDOWN")
                }
            )
            }








            

            post("/api/bot/setMessageReaction") {
                val headerToken = call.request.headers["X-Bot-Token"].orEmpty()
                val bearer = call.request.headers["Authorization"].bearerTokenOrNull().orEmpty()
                val token = headerToken.ifBlank { bearer }
                val bot = com.maodouchat.server.repository.BotRepository.authenticate(token)
                    ?: return@post call.respond(HttpStatusCode.Unauthorized, ErrorResponse("invalid bot token"))
                // 每 bot 限流：防单 bot 高频 fanout（WS + FCM 风暴）
                if (!botSendRateLimiter.acquire(bot.id, maxPerMinute = 60)) {
                    return@post call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作太频繁，请稍后再试"))
                }
                if (!com.maodouchat.server.service.RuntimeConfigService.isReactionsEnabled()) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("reactions_disabled"))
                }
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid json"))
                val messageId = obj["messageId"]?.jsonPrimitive?.content.orEmpty()
                val emoji = obj["emoji"]?.jsonPrimitive?.content.orEmpty().trim()
                if (messageId.isBlank() || emoji.isBlank()) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("messageId/emoji required"))
                }
                if (emoji !in ALLOWED_REACTION_EMOJIS) {
                    return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("unsupported emoji"))
                }
                val msg = messageRepo.getMessageById(messageId)
                    ?: return@post call.respond(HttpStatusCode.NotFound, ErrorResponse("message not found"))
                if (!chatRepo.isParticipant(msg.chatId, bot.id)) {
                    return@post call.respond(HttpStatusCode.Forbidden, ErrorResponse("bot not in chat"))
                }
                messageRepo.setReaction(
                    messageId = messageId,
                    userId = bot.id,
                    emoji = emoji,
                    requireBotDeliverable = true
                )
                    ?: return@post call.respond(HttpStatusCode.BadRequest, ErrorResponse("cannot react"))
                com.maodouchat.server.repository.BotRepository.logCommand(bot.id, msg.chatId, messageId, "setMessageReaction")
                val botReactions = messageRepo.getReactionsForViewer(messageId, bot.id)
                // 双向拉黑过滤，与 sendMessage 口径一致
                val botChatParticipants = chatRepo.getParticipantIds(msg.chatId)
                val botBlockedIds = try {
                    userRepo.blockedEitherWayIdsInTx(bot.id, botChatParticipants)
                } catch (_: Exception) { emptySet() }
                val botReactionViewers = botChatParticipants.filter { it !in botBlockedIds }
                val botReactionsByViewer = messageRepo.getReactionsForViewers(messageId, botReactionViewers)
                botReactionViewers.forEach { pid ->
                    botReactionsByViewer[pid]?.let { viewerReactions ->
                        val viewerPayload = MessageReactionUpdatedPayload(msg.chatId, messageId, bot.id, viewerReactions)
                        try {
                            sendToUser(
                                pid,
                                json.encodeToString(
                                    WsMessage.serializer(),
                                    WsMessage(
                                        "MESSAGE_REACTION_UPDATED",
                                        json.encodeToString(MessageReactionUpdatedPayload.serializer(), viewerPayload)
                                    )
                                )
                            )
                        } catch (e: CancellationException) {
                            throw e
                        } catch (_: Exception) {
                        }
                    }
                }
                call.respond(
                buildJsonObject {
put("ok", true)
put("messageId", messageId)
put("emoji", emoji)
put("reactions", Json.parseToJsonElement(Json.encodeToString(botReactions)))
                }
            )
            }

