                fanoutBotMessage(userRepo, chatRepo, json, bot.id, chatId, botMessage)
                call.respond(
                buildJsonObject {
put("ok", true)
put("messageId", msgId)
put("type", "SYSTEM")
put("level", level)
                }
            )
            }

