        authenticate("auth-jwt") {
            put("/api/chats/{chatId}/disappearing-messages") {
                if (call.rejectIfMaintenance()) return@put
                if (!RuntimeConfigService.isDisappearingMessagesEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("disappearing_messages_disabled"))
                    return@put
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfSuspended(userRepo, userId)) return@put
                val chatId = call.parameters["chatId"]!!
                val request = call.receiveBoundedText()?.let { parseJson<UpdateDisappearingMessagesRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("请求体无效"))
                    return@put
                }
                if (!chatRepo.isParticipant(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天"))
                    return@put
                }
                val result = runCatching {
                    chatRepo.setDisappearingMessages(chatId, userId, request.seconds)
                }.getOrElse { e ->
                    when (e.message) {
                        "group_not_supported" -> {
                            call.respond(HttpStatusCode.BadRequest, ErrorResponse("群聊暂不支持阅后即焚"))
                            return@put
                        }
                        "invalid_timer" -> {
                            call.respond(HttpStatusCode.BadRequest, ErrorResponse("不支持的销毁时长"))
                            return@put
                        }
                        "not_a_participant" -> {
                            call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天"))
                            return@put
                        }
                        else -> throw e
                    }
                }
                val wsJson = json.encodeToString(
                    WsMessage.serializer(),
                    WsMessage(
                        "DISAPPEARING_MESSAGES_UPDATED",
                        json.encodeToString(DisappearingMessagesResponse.serializer(), result)
                    )
                )
                chatRepo.getParticipantIds(chatId).forEach { pid -> sendToUser(pid, wsJson) }
                call.respond(result)
            }

            get("/api/chats/{chatId}/messages") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val chatId = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天消息"))
                    return@get
                }
                val since = call.request.queryParameters["since"]?.toLongOrNull()
                val before = call.request.queryParameters["before"]?.toLongOrNull()
                if (since != null) {
                    // 增量同步允许更大页：避免离线 backlog 被 route 的 100 上限截断后游标永久跳过中间段
                    val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 200).coerceIn(1, 500)
                    val sinceId = call.request.queryParameters["sinceId"]
                        ?.takeIf { it.isNotBlank() && it.length <= 100 }
                    // viewerId：过滤读者已拉黑发送者（含 SK_DIST），与实时 fanout 一致
                    call.respond(messageRepo.getMessagesSince(chatId, since, limit, sinceId, viewerId = userId))
                } else if (before != null) {
                    val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 100).coerceIn(1, 100)
                    val beforeId = call.request.queryParameters["beforeId"]
                        ?.takeIf { it.isNotBlank() && it.length <= 100 }
                    call.respond(messageRepo.getMessagesBefore(chatId, before, beforeId, limit, viewerId = userId))
                } else {
                    val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 50).coerceIn(1, 100)
                    call.respond(messageRepo.getMessages(chatId, limit, viewerId = userId))
                }
            }

            post("/api/chats/{chatId}/messages") {
                if (call.rejectIfMaintenance()) return@post
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                // 每用户发消息限流 - 防核心接口被刷/DoS（参照 attachment 限流模式）
                if (!aiRateLimiter.acquire("message_send:$userId", maxPerMinute = 120)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("发送过于频繁，请稍后再试"))
                    return@post
                }
                val chatId = call.parameters["chatId"]!!
                if (call.rejectIfMessageRestricted(userRepo, userId)) return@post
                if (!chatRepo.isParticipant(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权向该聊天发送消息"))
                    return@post
                }
                val req = call.receiveBoundedText(MAX_UPLOAD_JSON_BODY_CHARS)?.let { parseJson<SendMessageRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息内容无效"))
                    return@post
                }
                if (req.chatId != chatId) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("聊天 ID 不一致"))
                    return@post
                }
                if (!isValidMessagePayload(req.content, req.type, req.id)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息内容无效"))
                    return@post
                }
                val isGroup = chatRepo.getChatById(chatId)?.isGroup == true
                // 广播频道：仅创建者（OWNER）可发；订阅者只读（与群禁言一致由服务端强制）
                if (chatRepo.getChatType(chatId) == ChatType.CHANNEL && !chatRepo.isChannelOwner(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("频道为单向广播，仅创建者可发送消息"))
                    return@post
                }
                if (isGroup && chatRepo.isMuted(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法发送消息"))
                    return@post
                }
                // 1:1 拉黑预检：双向（与 sendMessage 事务内复检一致）
                if (!isGroup) {
                    val peers = chatRepo.getParticipantIds(chatId).filter { it != userId }
                    if (peers.any {
                            userRepo.hasBlocked(it, userId) || userRepo.hasBlocked(userId, it)
                        }
                    ) {
                        call.respond(HttpStatusCode.Forbidden, ErrorResponse("存在屏蔽关系，无法发送消息"))
                        return@post
                    }
                }
                val sealedHeader = call.request.headers["X-Maodouchat-Sealed-Sender-Cert"]
                val sealedOk = SealedSenderDelivery.authorize(
                    requested = req.sealedSender || !sealedHeader.isNullOrBlank() || !req.sealedSenderCertificate.isNullOrBlank(),
                    certificateHeader = sealedHeader,
                    certificateBody = req.sealedSenderCertificate,
                    userId = userId
                )
                if ((req.sealedSender || !req.sealedSenderCertificate.isNullOrBlank()) && !sealedOk) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("invalid sealed sender certificate"))
                    return@post
                }
                val sent = try {
                    messageRepo.sendMessage(chatId, userId, req.content, req.type, req.id, sealedSender = sealedOk)
                } catch (_: DuplicateMessageIdException) {
                    call.respond(HttpStatusCode.Conflict, ErrorResponse("消息 ID 已存在"))
                    return@post
                } catch (_: AttachmentNotReadyException) {
                    call.respond(HttpStatusCode.Conflict, ErrorResponse("附件尚未上传完成，请稍后重试"))
                    return@post
                } catch (_: NotParticipantException) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权向该聊天发送消息"))
                    return@post
                } catch (_: MutedException) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法发送消息"))
                    return@post
                } catch (_: BlockedException) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("对方已屏蔽你，无法发送消息"))
                    return@post
                } catch (_: InvalidMessageTypeException) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息类型无效"))
                    return@post
                }
                val message = sent.message
                val participants = sent.participantIds
                // 断线重连后以相同 messageId 重发（首次投递 ACK 丢失）：仓库层返回已存的既有消息。
                // 收件人首次投递时已收到 NEW_MESSAGE，这里不再二次 fan-out / 推送 / 触发 bot，避免重复消息与重复通知。
                if (!sent.wasExisting) {
                    // Notify chat bots via webhook (metadata; plaintext only for non-e2ee-looking content).
                    com.maodouchat.server.service.BotWebhookService.notifyChatEvent(
                        chatId = chatId,
                        event = "message",
                        messageId = message.id,
                        senderId = userId,
                        type = message.type,
                        textPreview = if (message.type in setOf("TEXT", "MARKDOWN", "SYSTEM", "NUDGE")) message.content.take(200) else null,
                        sealedSender = message.sealedSender
                    )
                    // 8.30 性能优化 A1：批量双向拉黑 + 批量静音（替代逐成员事务）
                    val blockedIds = try {
                        userRepo.blockedEitherWayIdsInTx(userId, participants)
                    } catch (_: Exception) { emptySet() }
                    val recipients = participants.filter { it !in blockedIds }
                    recipients.forEach { participantId ->
                        val viewerMsg = SealedSenderDelivery.forViewer(message, participantId)
                        val msgJson = json.encodeToString(WsMessage("NEW_MESSAGE", json.encodeToString(viewerMsg)))
                        sendToUser(participantId, msgJson)
                    }
                    // SK_DIST is crypto control — never wake devices with a message notification.
                    if (message.type != "SK_DIST" && !req.silent) {
                        val mutedIds = chatRepo.mutedUserIdsInTx(chatId, recipients)
                        pushService.enqueueEncryptedMessage(
                            recipientIds = recipients.filter { it !in mutedIds },
                            chatId = message.chatId,
                            messageId = message.id,
                            senderId = userId,
                            messageType = message.type,
                            sealedSender = message.sealedSender
                        )
                    }
                }
                call.respond(HttpStatusCode.Created, message)
            }

            put("/api/messages/{messageId}/status") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val messageId = call.parameters["messageId"]!!
                val message = messageRepo.getMessageById(messageId)
                if (message == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在"))
                    return@put
                }
                if (!chatRepo.isParticipant(message.chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权更新该消息状态"))
                    return@put
                }
                // 消息发送者不能更新自己消息的状态
                if (message.senderId == userId) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("不能更新自己消息的状态"))
                    return@put
                }
                val req = call.receiveBoundedText()?.let { parseJson<UpdateStatusRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put }
                if (req.messageId != messageId) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息 ID 不一致"))
                    return@put
                }
                if (req.status !in ALLOWED_STATUSES) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息状态无效"))
                    return@put
                }
                // 双向拉黑后不写回执、不通知发送方
                if (userRepo.isBlockedEitherWay(userId, message.senderId)) {
                    call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    return@put
                }
                if (!messageRepo.updateStatus(messageId, req.status, readerId = userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权更新该消息状态"))
                    return@put
                }
                // 群聊 READ 仅个人回执；全局 MESSAGE_STATUS READ 会让发送方误判全员已读
                val isGroup = chatRepo.getChatById(message.chatId)?.isGroup == true
                if (!(isGroup && req.status == "READ")) {
                    val statusJson = json.encodeToString(
                        WsMessage(
                            "MESSAGE_STATUS",
                            json.encodeToString(
                                StatusUpdatePayload.serializer(),
                                StatusUpdatePayload(messageId, req.status)
                            )
                        )
                    )
                    sendToUser(message.senderId, statusJson)
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            // 撤回消息（仅发送者可撤回，5 分钟内有效，会通知聊天参与者）
            post("/api/messages/{messageId}/revoke") {

                if (!RuntimeConfigService.isMessageRevokeEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("message_revoke_disabled"))
                    return@post
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfMessageRestricted(userRepo, userId)) return@post
                // 8.40：编辑/撤回/删除共享 mutation 限流
                if (!messageMutateRateLimiter.acquire(userId, maxPerMinute = 60)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@post
                }
                val messageId = call.parameters["messageId"]!!
                val message = messageRepo.getMessageById(messageId)
                if (message == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在"))
                    return@post
                }
                if (!chatRepo.isParticipant(message.chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权撤回该消息"))
                    return@post
                }
                if (chatRepo.getChatById(message.chatId)?.isGroup == true && chatRepo.isMuted(message.chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法撤回消息"))
                    return@post
                }
                // mark-first：仅 Applied 才清磁盘 / 广播；AlreadyDone 幂等 200
                // 附件行已在 revoke 同事务删除，这里只按 ID 删磁盘
                when (val revoke = messageRepo.revokeMessage(messageId, userId)) {
                    MessageRepository.RevokeResult.Failure -> {
                        call.respond(HttpStatusCode.Forbidden, ErrorResponse("只能撤回自己 5 分钟内发送的消息"))
                        return@post
                    }
                    MessageRepository.RevokeResult.AlreadyDone -> {
                        call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                        return@post
                    }
                    is MessageRepository.RevokeResult.Applied -> {
                        revoke.deletedAttachmentIds.forEach(EncryptedAttachmentStorage::delete)
                        val revokeNotification = json.encodeToString(
                            WsMessage.serializer(),
                            WsMessage("MESSAGE_REVOKED", json.encodeToString(
                                DeleteMessagePayload.serializer(),
                                DeleteMessagePayload(messageId, message.chatId)
                            ))
                        )
                        // 双向拉黑过滤，与 NEW_MESSAGE fanout 口径一致（发送者拉黑对方也不推送）
                        val participants = chatRepo.getParticipantIds(message.chatId)
                        val blockedIds = try {
                            userRepo.blockedEitherWayIdsInTx(userId, participants)
                        } catch (_: Exception) { emptySet() }
                        participants.forEach { participantId ->
                            if (participantId != userId && participantId !in blockedIds) {
                                sendToUser(participantId, revokeNotification)
                            }
                        }
                        call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    }
                }
            }

            // 编辑消息（具体窗口由消息类型策略决定）
            put("/api/messages/{messageId}") {

                if (!RuntimeConfigService.isMessageEditEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("message_edit_disabled"))
                    return@put
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfMessageRestricted(userRepo, uid)) return@put
                // 8.40：编辑/撤回/删除共享限流——每次 mutation 向全成员 WS 广播，无上限即成 fanout 放大
                if (!messageMutateRateLimiter.acquire(uid, maxPerMinute = 60)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@put
                }
                val mid = call.parameters["messageId"]!!
                val req = call.receiveBoundedText()?.let { parseJson<SendMessageRequest>(it) } ?: run { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put }
                val msg = messageRepo.getMessageById(mid) ?: run { call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在")); return@put }
                if (!chatRepo.isParticipant(msg.chatId, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@put }
                if (chatRepo.getChatById(msg.chatId)?.isGroup == true && chatRepo.isMuted(msg.chatId, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法编辑消息"))
                    return@put
                }
                // 编辑后的内容必须与原消息类型一致，且通过长度/格式校验
                if (!isValidMessagePayload(req.content, msg.type, null)) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("消息内容无效")); return@put }
                if (!messageRepo.editMessage(mid, uid, req.content)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无法编辑该消息，请确认消息由你发送且仍在允许编辑的时间内")); return@put }
                val editedMsg = messageRepo.getMessageById(mid)
                val editedAt = editedMsg?.editedAt ?: System.currentTimeMillis()
                val ej = json.encodeToString(WsMessage.serializer(), WsMessage("MESSAGE_EDITED", json.encodeToString(MessageEditedPayload.serializer(), MessageEditedPayload(mid, msg.chatId, req.content, editedAt))))
                // 8.48 修复 H6：批量双向拉黑过滤（此前逐成员 hasBlocked → N 次查询）
                val participants = try { chatRepo.getParticipantIds(msg.chatId) } catch (_: Exception) { emptyList() }
                val blockedIds = try { userRepo.blockedEitherWayIdsInTx(uid, participants) } catch (_: Exception) { emptySet() }
                participants.forEach { participantId ->
                    if (participantId == uid || participantId !in blockedIds) {
                        sendToUser(participantId, ej)
                    }
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            // 群管理：加人（仅 OWNER/ADMIN）
            post("/api/chats/{chatId}/members") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@post
                val req = call.receiveBoundedText()?.let { parseJson<CreateChatRequest>(it) } ?: run { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                val requestedIds = req.participantIds.map(String::trim)
                if (requestedIds.isEmpty() || requestedIds.any(String::isBlank) || requestedIds.distinct().size != requestedIds.size) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("成员不能为空或重复")); return@post
                }
                // 路由层预检成员数上限：防止超大 IN 列表打爆 PostgreSQL 参数上限（65535）
                val chatType = chatRepo.getChatType(cid)
                val memberCap = if (chatType == ChatType.CHANNEL) MAX_CHANNEL_SUBSCRIBERS else maxGroupMembers()
                if (requestedIds.size > memberCap) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("一次性添加成员不能超过 $memberCap 人")); return@post
                }
                val addResult = if (chatType == ChatType.CHANNEL) {
                    chatRepo.addGroupMembersAs(cid, uid, requestedIds, MAX_CHANNEL_SUBSCRIBERS)
                } else {
                    chatRepo.addGroupMembersAs(cid, uid, requestedIds, maxGroupMembers())
                }
                if (addResult.result == ChatRepository.GroupMemberMutationResult.USER_NOT_FOUND) {
                    call.respond(
                        HttpStatusCode.NotFound,
                        ErrorResponse("用户不存在: ${addResult.missingUserId.orEmpty()}", code = "GROUP_USER_NOT_FOUND")
                    )
                    return@post
                }
                if (addResult.result == ChatRepository.GroupMemberMutationResult.BLOCKED) {
                    call.respond(
                        HttpStatusCode.Forbidden,
                        ErrorResponse(
                            "无法添加已屏蔽的用户: ${addResult.blockedUserId.orEmpty()}",
                            code = "GROUP_MEMBER_BLOCKED"
                        )
                    )
                    return@post
                }
                if (call.respondGroupMemberMutationFailure(addResult.result)) return@post
                val addedIds = addResult.addedUserIds
                if (addedIds.isNotEmpty()) {
                    notifyGroupRevisionChanged(
                        chatRepo = chatRepo,
                        json = json,
                        chatId = cid,
                        reason = "MEMBER_ADDED",
                        actorId = uid,
                        targetUserId = addedIds.firstOrNull()
                    )
                }
                val updatedChat = chatRepo.getChatById(cid)
                if (updatedChat == null) {
                    call.respond(HttpStatusCode.InternalServerError, ErrorResponse("群聊状态异常，请刷新"))
                    return@post
                }
                call.respond(updatedChat)
            }
            // 群管理：踢人（OWNER 可踢任何人，ADMIN 只能踢 MEMBER，不能踢 OWNER）
            delete("/api/chats/{chatId}/members/{memberId}") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!; val mid = call.parameters["memberId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@delete
                val recipientsBefore = chatRepo.getParticipantIds(cid)
                val mutation = chatRepo.removeGroupMemberAs(cid, uid, mid)
                if (call.respondGroupMemberMutationFailure(mutation)) return@delete
                notifyGroupRevisionChanged(
                    chatRepo = chatRepo,
                    json = json,
                    chatId = cid,
                    reason = "MEMBER_REMOVED",
                    actorId = uid,
                    targetUserId = mid,
                    recipientIds = recipientsBefore
                )
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
            // 群管理：改名（仅 OWNER/ADMIN）
            put("/api/chats/{chatId}/name") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val b = call.receiveBoundedText()?.let { parseJson<CreateChatRequest>(it) }
                val newName = b?.groupName.orEmpty().trim()
                if (newName.isBlank() || newName.length > 50) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("群名长度需 1-50 字符")); return@put }
                val mutation = chatRepo.updateGroupNameAsAdmin(cid, uid, newName)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "GROUP_RENAMED", uid)
                val updatedChat = chatRepo.getChatById(cid)
                if (updatedChat == null) {
                    call.respond(HttpStatusCode.InternalServerError, ErrorResponse("群聊状态异常，请刷新"))
                    return@put
                }
                call.respond(updatedChat)
            }
            // 群公告（仅 OWNER/ADMIN 可编辑；所有成员可通过聊天详情读取）
            put("/api/chats/{chatId}/announcement") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val req = call.receiveBoundedText()?.let { parseJson<UpdateGroupAnnouncementRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val announcement = req.announcement.trim().takeIf { it.isNotBlank() }
               if ((announcement?.length ?: 0) > 1200) {
                   call.respond(HttpStatusCode.BadRequest, ErrorResponse("群公告不能超过 1200 字符")); return@put
               }
                val mutation = chatRepo.updateGroupAnnouncementAsAdmin(cid, uid, announcement)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "ANNOUNCEMENT_UPDATED", uid)
                val updatedChat = chatRepo.getChatById(cid)
                if (updatedChat == null) {
                    call.respond(HttpStatusCode.InternalServerError, ErrorResponse("群聊状态异常，请刷新"))
                    return@put
                }
                call.respond(updatedChat)
            }
            // 群邀请二维码（仅 OWNER/ADMIN 可生成；扫码者通过 token 入群）
            post("/api/chats/{chatId}/invite-token") {
                if (!RuntimeConfigService.isGroupInvitesEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("group_invites_disabled"))
                    return@post
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@post
                // 广播频道不开放邀请链接：订阅由创建者添加
                if (chatRepo.getChatType(cid) == ChatType.CHANNEL) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("频道不支持邀请链接"))
                    return@post
                }
                val body = call.receiveBoundedText()
                val request = body?.takeIf { it.isNotBlank() }?.let { parseJson<CreateGroupInviteRequest>(it) }
                    ?: CreateGroupInviteRequest(rotate = call.request.queryParameters["rotate"] == "1")
                if (request.expiresInSeconds !in 300L..(30L * 24L * 60L * 60L) || request.maxUses !in 1..1000) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("邀请有效期或使用次数无效")); return@post
                }
                val expiresAt = System.currentTimeMillis() + request.expiresInSeconds * 1000L
                val mutation = chatRepo.configureGroupInviteAsAdmin(cid, uid, request.rotate, expiresAt, request.maxUses)
                if (call.respondGroupMemberMutationFailure(mutation.result)) return@post
                val invite = mutation.invite ?: run {
                    call.respond(HttpStatusCode.InternalServerError, ErrorResponse("生成群邀请失败")); return@post
                }
                call.respond(GroupInviteResponse(invite.token, "maodouchat:chat-invite:v1:${invite.token}", chatRepo.getChatById(cid), invite.expiresAt, invite.maxUses, invite.usedCount, invite.remainingUses))
            }

            post("/api/chats/{chatId}/avatar") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@post
                if (!avatarRateLimiter.acquire(uid, maxPerMinute = 10)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("头像操作过于频繁，请稍后再试"))
                    return@post
                }
                if (!chatRepo.isOwnerOrAdmin(cid, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("只有群主或管理员可以修改群头像", code = "GROUP_PERMISSION_DENIED"))
                    return@post
                }
                val request = call.receiveBoundedText(MAX_UPLOAD_JSON_BODY_CHARS)?.let { parseJson<UploadAvatarRequest>(it) }
                    ?: run { call.respond(HttpStatusCode.BadRequest, ErrorResponse("头像参数无效")); return@post }
                val avatarUrl = try {
                    com.maodouchat.server.service.FileStorageService.saveGroupAvatar(request.base64Data, cid)
                } catch (error: IllegalArgumentException) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse(error.message ?: "群头像无效")); return@post
                }
                var committed = false
                try {
                    val mutation = chatRepo.updateGroupAvatarAsAdmin(cid, uid, avatarUrl)
                    if (mutation.result != ChatRepository.GroupMemberMutationResult.UPDATED) {
                        call.respondGroupMemberMutationFailure(mutation.result)
                        return@post
                    }
                    committed = true
                    com.maodouchat.server.service.FileStorageService.deleteGroupAvatarUrl(mutation.previousAvatarUrl, cid)
                    notifyGroupRevisionChanged(chatRepo, json, cid, "AVATAR_UPDATED", uid)
                    call.respond(
                buildJsonObject {
put("status", "ok")
put("avatarUrl", avatarUrl)
                }
            )
                } finally {
                    if (!committed) {
                        com.maodouchat.server.service.FileStorageService.deleteGroupAvatarUrl(avatarUrl, cid)
                    }
                }
            }
            // 群成员列表（带角色信息）
            get("/api/chats/{chatId}/members") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(cid, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@get }
                val members = chatRepo.getGroupMembers(cid, viewerId = uid)
                // 9.135：频道订阅者（非管理者）只能看到管理者列表——此前任意订阅者可枚举
                // 全部订阅者的昵称/头像/在线状态（最多 5000 人）
                if (chatRepo.getChatType(cid) == ChatType.CHANNEL && !chatRepo.isOwnerOrAdmin(cid, uid)) {
                    call.respond(members.filter { it.role == "OWNER" || it.role == "ADMIN" })
                } else {
                    call.respond(members)
                }
            }
            get("/api/chats/{chatId}/audit") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(cid, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权查看群操作记录")); return@get }
                // 9.135：频道审计含订阅者进出记录，仅管理者可读，防止订阅者互相枚举
                if (chatRepo.getChatType(cid) == ChatType.CHANNEL && !chatRepo.isOwnerOrAdmin(cid, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权查看群操作记录")); return@get
                }
                // 8.64：支持 offset 分页（历史审计翻页）
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 50).coerceIn(1, 100)
                val offset = (call.request.queryParameters["offset"]?.toIntOrNull() ?: 0).coerceAtLeast(0)
                call.respond(chatRepo.getGroupAudit(cid, limit, offset, viewerId = uid))
            }
            post("/api/chats/{chatId}/sender-key-distributions") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(cid, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@post }
                val req = call.receiveBoundedText()?.let { parseJson<SenderKeyDistributionReportRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post
                }
                if (req.epoch < 0 || req.targets.size > 500 || req.targets.any { it.userId.isBlank() || it.deviceId !in 1..255 }) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("分发状态参数无效")); return@post
                }
                val participantIds = chatRepo.getParticipantIds(cid).toSet()
                if (req.targets.any { it.userId !in participantIds }) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("只能上报群成员设备的密钥分发状态")); return@post
                }
                senderKeyDistributionRepo.record(cid, req.epoch, uid, req.messageId, req.targets)
                call.respond(senderKeyDistributionRepo.getStatus(cid, uid, req.epoch))
            }
            get("/api/chats/{chatId}/sender-key-distributions") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(cid, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@get }
                // 9.135：密钥分发状态含全部参与者（含订阅者）的设备清单，频道仅管理者可读
                if (chatRepo.getChatType(cid) == ChatType.CHANNEL && !chatRepo.isOwnerOrAdmin(cid, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权查看密钥分发状态")); return@get
                }
                val epoch = call.request.queryParameters["epoch"]?.toLongOrNull()
                val currentDeviceId = call.request.queryParameters["currentDeviceId"]?.toIntOrNull()
                if (currentDeviceId != null && currentDeviceId !in 1..255) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备参数无效")); return@get
                }
                val participants = chatRepo.getParticipantIds(cid)
                val expectedTargets = signalKeyRepo.getConfirmedDeviceTargets(participants)
                    .filterNot { (userId, deviceId) ->
                        userId == uid && (currentDeviceId == null || deviceId == currentDeviceId)
                    }
                    .toSet()
                call.respond(senderKeyDistributionRepo.getStatus(cid, uid, epoch, expectedTargets))
            }
            // 修改成员角色（仅 OWNER）
            put("/api/chats/{chatId}/members/{memberId}/role") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!; val mid = call.parameters["memberId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val req = call.receiveBoundedText()?.let { parseJson<UpdateMemberRoleRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                if (req.role !in listOf("ADMIN", "MEMBER")) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("角色只能是 ADMIN 或 MEMBER")); return@put
                }
                val mutation = chatRepo.updateGroupMemberRoleAsOwner(cid, uid, mid, req.role)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "ROLE_UPDATED", uid, mid)
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
            // 转让群主：角色交换必须在同一数据库事务完成，避免出现双群主或无群主窗口。
            put("/api/chats/{chatId}/members/{memberId}/ownership") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!; val mid = call.parameters["memberId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                when (chatRepo.transferOwnership(cid, uid, mid)) {
                    ChatRepository.TransferOwnershipResult.TRANSFERRED -> {
                        notifyGroupRevisionChanged(chatRepo, json, cid, "OWNERSHIP_TRANSFERRED", uid, mid)
                        call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    }
                    ChatRepository.TransferOwnershipResult.CHAT_NOT_FOUND,
                    ChatRepository.TransferOwnershipResult.NOT_GROUP ->
                        call.respond(HttpStatusCode.NotFound, ErrorResponse("群聊不存在"))
                    ChatRepository.TransferOwnershipResult.NOT_OWNER ->
                        call.respond(HttpStatusCode.Forbidden, ErrorResponse("只有群主可以转让群主身份"))
                    ChatRepository.TransferOwnershipResult.TARGET_NOT_PARTICIPANT ->
                        call.respond(HttpStatusCode.NotFound, ErrorResponse("该用户不是群成员"))
                    ChatRepository.TransferOwnershipResult.SAME_USER ->
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能将群主身份转让给自己"))
                }
            }
            // 设置我在本群昵称
            put("/api/chats/{chatId}/members/me/nickname") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject; val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val req = call.receiveBoundedText()?.let { parseJson<UpdateGroupNicknameRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val normalizedNickname = req.groupNickname.trim()
                if (normalizedNickname.length > 100) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("群昵称不能超过 100 字符")); return@put
                }
                val nickname = normalizedNickname.takeIf(String::isNotBlank)
                val mutation = chatRepo.updateOwnGroupNickname(cid, uid, nickname)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "NICKNAME_UPDATED", uid, uid)
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
            // 设置成员头衔（OWNER/ADMIN）
            put("/api/chats/{chatId}/members/{memberId}/title") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!; val mid = call.parameters["memberId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val req = call.receiveBoundedText()?.let { parseJson<UpdateMemberTitleRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val normalizedTitle = req.title.trim()
                if (normalizedTitle.length > 50) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("成员头衔不能超过 50 字符")); return@put
                }
                val title = normalizedTitle.takeIf(String::isNotBlank)
                val mutation = chatRepo.updateGroupMemberTitleAsAdmin(cid, uid, mid, title)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "TITLE_UPDATED", uid, mid)
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
            // 设置成员禁言（OWNER 可禁言 ADMIN/MEMBER；ADMIN 只能禁言 MEMBER）
            put("/api/chats/{chatId}/members/{memberId}/mute") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!; val mid = call.parameters["memberId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@put
                val req = call.receiveBoundedText()?.let { parseJson<UpdateMemberMuteRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val now = System.currentTimeMillis()
                val mutedUntil = when {
                    req.mutedUntil <= now -> 0L
                    req.mutedUntil > now + MAX_MUTE_DURATION_MS -> {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("禁言最长不能超过 30 天")); return@put
                    }
                    else -> req.mutedUntil
                }
                val mutation = chatRepo.updateGroupMemberMuteAsAdmin(cid, uid, mid, mutedUntil)
                if (call.respondGroupMemberMutationFailure(mutation)) return@put
                notifyGroupRevisionChanged(chatRepo, json, cid, "MUTE_UPDATED", uid, mid)
                call.respond(
                buildJsonObject {
put("status", "ok")
put("mutedUntil", mutedUntil)
                }
            )
            }
            // 0.99：全员静音（除群主/管理员；mutedUntil=0 解除全员）——内部按角色过滤，批量 UPDATE 一次
            post("/api/chats/{chatId}/mute-all") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["chatId"]!!
                if (call.rejectIfSuspended(userRepo, uid)) return@post
                if (!chatRepo.isOwnerOrAdmin(cid, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("只有群主或管理员可以全员静音", code = "GROUP_PERMISSION_DENIED"))
                    return@post
                }
                val req = call.receiveBoundedText()?.let { parseJson<UpdateMemberMuteRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post
                }
                val now = System.currentTimeMillis()
                val mutedUntil = when {
                    req.mutedUntil <= now -> 0L
                    req.mutedUntil > now + MAX_MUTE_DURATION_MS -> {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("禁言最长不能超过 30 天")); return@post
                    }
                    else -> req.mutedUntil
                }
                val memberIds = chatRepo.getParticipantIds(cid)
                val updated = chatRepo.muteGroupMembersAsAdmin(cid, uid, memberIds, mutedUntil)
                if (updated > 0) {
                    notifyGroupRevisionChanged(chatRepo, json, cid, "MUTE_UPDATED", uid, null)
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
put("updated", updated)
                }
            )
            }
            // 屏蔽
            post("/api/users/block/{uid}") {
                if (!RuntimeConfigService.isBlockReportEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("block_report_disabled"))
                    return@post
                }
                val blockerId = call.principal<JWTPrincipal>()!!.payload.subject
                val blockedId = call.parameters["uid"].orEmpty()
                if (!userRepo.blockUser(blockerId, blockedId)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("无法拉黑该用户"))
                    return@post
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
            delete("/api/users/block/{uid}") { userRepo.unblockUser(call.principal<JWTPrincipal>()!!.payload.subject, call.parameters["uid"]!!); call.respond(
                buildJsonObject {
put("status", "ok")
                }
            ) }
            get("/api/users/blocks") { call.respond(userRepo.getBlockedUsers(call.principal<JWTPrincipal>()!!.payload.subject)) }
            get("/api/users/blocks/details") { call.respond(userRepo.getBlockedUserDetails(call.principal<JWTPrincipal>()!!.payload.subject)) }
            post("/api/reports") {

                if (!RuntimeConfigService.isBlockReportEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("block_report_disabled"))
                    return@post
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!reportRateLimiter.acquire(uid, maxPerMinute = 5)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("举报过于频繁，请稍后再试"))
                    return@post
                }
                val req = call.receiveBoundedText()?.let { parseJson<CreateReportRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@post
                }
                when (val result = reportRepo.createReport(uid, req)) {
                    is ReportRepository.CreateResult.Success -> call.respond(HttpStatusCode.Created, result.report)
                    is ReportRepository.CreateResult.Failure -> call.respond(HttpStatusCode.BadRequest, ErrorResponse(result.message))
                }
            }

            get("/api/reports/mine") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 50).coerceIn(1, 100)
                call.respond(reportRepo.getMyReports(uid, limit))
            }

            // 路径从 /api/admin/reports 改为 /api/moderator/reports，避免与 AdminRouting.kt 的 master admin 版本冲突
            // admin.js（web admin，admin-jwt）仍走 /api/admin/reports；app 客户端（moderator，auth-jwt）走此路径
            get("/api/moderator/reports") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@get
                }
                val status = call.request.queryParameters["status"]
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 100).coerceIn(1, 200)
                val offset = (call.request.queryParameters["offset"]?.toLongOrNull() ?: 0L).coerceAtLeast(0L)
                call.respond(reportRepo.getReports(status, limit, offset))
            }

            put("/api/moderator/reports/{reportId}/status") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@put
                }
                val reportId = call.parameters["reportId"].orEmpty()
                val req = call.receiveBoundedText()?.let { parseJson<UpdateReportStatusRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@put
                }
                when (val result = reportRepo.updateReportStatus(reportId, uid, req.status, req.resolutionNote)) {
                    is ReportRepository.UpdateResult.Success -> call.respond(result.report)
                    is ReportRepository.UpdateResult.Failure -> {
                        // 8.42：资源不存在 404、状态冲突 409 与参数错误 400 分离
                        val status = when (result.message) {
                            "举报不存在" -> HttpStatusCode.NotFound
                            "已处置的举报不能变更状态" -> HttpStatusCode.Conflict
                            else -> HttpStatusCode.BadRequest
                        }
                        call.respond(status, ErrorResponse(result.message))
                    }
                }
            }

            post("/api/moderator/reports/{reportId}/action") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@post
                }
                val reportId = call.parameters["reportId"].orEmpty()
                val req = call.receiveBoundedText()?.let { parseJson<ApplyReportActionRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@post
                }
                val action = req.action.trim().uppercase()
                val existingReport = reportRepo.getReport(reportId) ?: run {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("举报不存在"))
                    return@post
                }
                // 只读校验在标记前完成；处置对象 userId 在此冻结，避免 mark 后内容被删导致限制落空
                val frozenRestrictionTargetUserId: String? = when (action) {
                    "NO_ACTION" -> null
                    "DELETE_CONTENT" -> {
                        if (existingReport.targetType !in setOf("MESSAGE", "POST", "COMMENT")) {
                            call.respond(HttpStatusCode.BadRequest, ErrorResponse("该举报类型不能删除内容"))
                            return@post
                        }
                        null
                    }
                    "RESTRICT_MESSAGES_24H", "RESTRICT_POSTS_7D", "SUSPEND_24H" -> {
                        val targetUserId = when (existingReport.targetType) {
                            "USER" -> existingReport.targetId
                            "MESSAGE" -> messageRepo.getSenderId(existingReport.messageId ?: existingReport.targetId)
                            "POST" -> postRepo.getPostAuthorId(existingReport.targetId)
                            "COMMENT" -> postRepo.getCommentAuthorId(existingReport.targetId)
                            else -> null
                        }
                        if (targetUserId.isNullOrBlank()) {
                            call.respond(HttpStatusCode.BadRequest, ErrorResponse("无法定位被处置用户"))
                            return@post
                        }
                        if (targetUserId == uid) {
                            call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能处置自己"))
                            return@post
                        }
                        if (hasContentModerationAccess(userRepo, targetUserId)) {
                            call.respond(HttpStatusCode.Forbidden, ErrorResponse("不能通过举报处置审核员或超级管理员账号"))
                            return@post
                        }
                        targetUserId
                    }
                    else -> {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("处置动作无效"))
                        return@post
                    }
                }
                // 原子标记：仅 Applied 时执行副作用，避免双点重复封禁/删内容
                when (val mark = reportRepo.markActionTaken(reportId, uid, action, req.resolutionNote)) {
                    is ReportRepository.ActionMarkResult.Failure -> {
                        val status = if (mark.message == "举报不存在") HttpStatusCode.NotFound else HttpStatusCode.BadRequest
                        call.respond(status, ErrorResponse(mark.message))
                        return@post
                    }
                    is ReportRepository.ActionMarkResult.AlreadyDone -> {
                        call.respond(mark.report)
                        return@post
                    }
                    is ReportRepository.ActionMarkResult.Applied -> {
                        val report = mark.report
                        when (action) {
                            "NO_ACTION" -> Unit
                            "DELETE_CONTENT" -> {
                                when (report.targetType) {
                                    "MESSAGE" -> {
                                        val messageId = report.messageId ?: report.targetId
                                        val deleted = messageRepo.deleteMessageForModeration(messageId)
                                        if (deleted.ok == true) {
                                            deleted.deletedAttachmentIds.forEach(EncryptedAttachmentStorage::delete)
                                            val chatId = deleted.message?.chatId
                                            if (chatId != null) {
                                                val deleteNotification = json.encodeToString(
                                                    WsMessage.serializer(),
                                                    WsMessage("MESSAGE_DELETED", json.encodeToString(
                                                        DeleteMessagePayload.serializer(),
                                                        DeleteMessagePayload(messageId, chatId)
                                                    ))
                                                )
                                                chatRepo.getParticipantIds(chatId).forEach { participantId ->
                                                    sendToUser(participantId, deleteNotification)
                                                }
                                            }
                                        }
                                    }
                                    "POST" -> {
                                        postRepo.deletePostForModeration(report.targetId)
                                        broadcastPostDeleted(report.targetId)
                                    }
                                    "COMMENT" -> postRepo.deleteCommentForModeration(report.targetId)
                                    else -> Unit
                                }
                            }
                            "RESTRICT_MESSAGES_24H", "RESTRICT_POSTS_7D", "SUSPEND_24H" -> {
                                val targetUserId = frozenRestrictionTargetUserId
                                if (!targetUserId.isNullOrBlank() &&
                                    targetUserId != uid &&
                                    !hasContentModerationAccess(userRepo, targetUserId)
                                ) {
                                    userRepo.applyModerationRestriction(targetUserId, action)
                                    if (action == "SUSPEND_24H") {
                                        authTokenRepo.rotateAccessTokenVersion(targetUserId)
                                        pushTokenRepo.removeAllForUser(targetUserId)
                                        disconnectUserSessions(targetUserId, "账号已被临时封禁")
                                    }
                                }
                            }
                        }
                        call.respond(report)
                    }
                }
            }

            get("/api/admin/moderation/rules") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@get
                }
                call.respond(moderationRuleRepo.getRules())
            }

            put("/api/admin/moderation/rules/{ruleId}") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@put
                }
                val ruleId = call.parameters["ruleId"].orEmpty()
                val req = call.receiveBoundedText()?.let { parseJson<UpdateModerationRuleRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@put
                }
                // 8.32 一致性：资源不存在 404、参数问题 400（此前合并为一个 400）
                if (!moderationRuleRepo.ruleExists(ruleId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("规则不存在"))
                    return@put
                }
                val updated = moderationRuleRepo.updateRule(ruleId, req)
                if (updated == null) call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                else call.respond(updated)
            }

            get("/api/admin/moderation/events") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@get
                }
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 100).coerceIn(1, 200)
                val needsReview = call.request.queryParameters["needsReview"]?.toBooleanStrictOrNull()
                call.respond(moderationRuleRepo.getRiskEvents(limit, needsReview))
            }

            post("/api/admin/moderation/events/{eventId}/ack") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!hasContentModerationAccess(userRepo, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("需要审核员权限"))
                    return@post
                }
                val eventId = call.parameters["eventId"].orEmpty()
                if (!moderationRuleRepo.acknowledgeRiskEvent(eventId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("风险事件不存在"))
                    return@post
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            get("/api/ai/settings") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val chatId = call.request.queryParameters["chatId"]?.takeIf(String::isNotBlank)
                if (chatId != null && !chatRepo.isParticipant(chatId, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天"))
                    return@get
                }
                call.respond(aiRepo.getSettings(uid, chatId))
            }

            put("/api/ai/settings") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val req = call.receiveBoundedText()?.let { parseJson<AiSettingsRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效"))
                    return@put
                }
                val chatId = req.chatId?.takeIf(String::isNotBlank)
