                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("ai_analyze_image_disabled"))
                    return@post
                }
                if (!RuntimeConfigService.isAiEnabled()) {
                    return@post call.respond(HttpStatusCode.ServiceUnavailable, ErrorResponse("AI temporarily disabled"))
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!aiRateLimiter.acquire("image_analyze:$uid", maxPerMinute = 10)) {
                    aiRepo.recordAudit(uid, null, "image_analyze", null, "rate_limited", 0, error = "rate_limited")
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("AI 请求过于频繁"))
                    return@post
                }
                val request = call.receiveBoundedText(MAX_UPLOAD_JSON_BODY_CHARS)
                    ?.let { parseJson<AiImageAnalyzeRequest>(it) }
                if (request == null || !isValidAiImageAnalyzePayload(request)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("图片分析内容无效"))
                    return@post
                }
                if (!chatRepo.isParticipant(request.chatId, uid)) {
                    aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "forbidden", 0, 1, error = "not_participant")
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天"))
                    return@post
                }
                if (!aiRepo.isEnabled(uid, request.chatId)) {
                    aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "disabled", 0, 1)
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("AI 功能已关闭"))
                    return@post
                }
                val image = validateAiImage(request.imageBase64) ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("图片格式或尺寸无效"))
                    return@post
                }
                val startedAt = System.currentTimeMillis()
                // 8.52 修复 AI-1：按图片字节保守估算 token（此前 ≈1 token）
                val estTokens = estimateMultimodalTokens(image.byteCount.toLong())
                val budget = aiGateway.checkBudget(uid, estTokens)
                if (budget is com.maodouchat.server.service.BudgetResult.Exceeded) {
                    call.response.header(HttpHeaders.RetryAfter, budget.retryAfterSeconds.toString())
                    aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "budget_exceeded", image.byteCount, durationMs = System.currentTimeMillis() - startedAt, error = "budget_exceeded")
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("AI 用量已达每日上限", code = "AI_BUDGET_EXCEEDED"))
                    return@post
                }
                when (val result = aiGateway.analyzeImage(image.base64, image.mimeType, request.mode)) {
                    is AiGatewayResult.Success -> {
                        aiRepo.recordAudit(uid, request.chatId, "image_analyze", result.model, "success", image.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, inputTokens = result.inputTokens, outputTokens = result.outputTokens)
                        call.respond(AiImageAnalyzeResponse(result.value.take(6_000), request.mode, result.model))
                    }
                    AiGatewayResult.NotConfigured -> {
                        aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "not_configured", image.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt)
                        call.respond(HttpStatusCode.ServiceUnavailable, ErrorResponse("AI 服务未配置"))
                    }
                    is AiGatewayResult.UpstreamError -> {
                        aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "upstream_error", image.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, error = result.message)
                        if (result.retryAfterSeconds != null) {
                            call.response.header(HttpHeaders.RetryAfter, result.retryAfterSeconds.toString())
                        }
                        call.respond(HttpStatusCode.BadGateway, ErrorResponse("AI 服务暂时不可用，请稍后重试"))
                    }
                    is AiGatewayResult.InvalidResponse -> {
                        aiRepo.recordAudit(uid, request.chatId, "image_analyze", null, "invalid_response", image.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, error = result.message)
                        call.respond(HttpStatusCode.BadGateway, ErrorResponse(result.message))
                    }
                }
            }

            post("/api/ai/analyze-file") {
                if (!RuntimeConfigService.isAiAnalyzeFileEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("ai_analyze_file_disabled"))
                    return@post
                }
                if (!RuntimeConfigService.isAiEnabled()) {
                    return@post call.respond(HttpStatusCode.ServiceUnavailable, ErrorResponse("AI temporarily disabled"))
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!aiRateLimiter.acquire("file_analyze:$uid", maxPerMinute = 8)) {
                    aiRepo.recordAudit(uid, null, "file_analyze", null, "rate_limited", 0, error = "rate_limited")
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("AI 请求过于频繁"))
                    return@post
                }
                val request = call.receiveBoundedText(MAX_UPLOAD_JSON_BODY_CHARS)
                    ?.let { parseJson<AiFileAnalyzeRequest>(it) }
                if (request == null || !isValidAiFileAnalyzePayload(request)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("文件分析内容无效"))
                    return@post
                }
                if (!chatRepo.isParticipant(request.chatId, uid)) {
                    aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "forbidden", 0, 1, error = "not_participant")
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天"))
                    return@post
                }
                if (!aiRepo.isEnabled(uid, request.chatId)) {
                    aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "disabled", 0, 1)
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("AI 功能已关闭"))
                    return@post
                }
                val file = validateAiFile(request.fileBase64, request.fileName, request.mimeType) ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("仅支持有效的 PDF、TXT、Markdown、CSV、JSON 或 XML 文件"))
                    return@post
                }
                val startedAt = System.currentTimeMillis()
                // 8.52 修复 AI-1：文件内容 + 问题文本一起估算（此前只算 ≤500 字的问题）
                // 9.161：非 PDF 文本走 base64→UTF-8 解码进 prompt（服务端 take(120_000)），
                // 按解码字符数估算——此前统一按字节 256:1 折算，实际 prompt 大一个量级，
                // 日预算预检低估、可高频调用绕过
                val estTokens = if (file.mimeType == "application/pdf") {
                    estimateMultimodalTokens(file.byteCount.toLong(), request.question)
                } else {
                    val decodedChars = (file.byteCount.toLong() * 3L / 4L).coerceAtMost(120_000L)
                    maxOf(1L, decodedChars / 4L + (request.question?.length ?: 0) / 4L)
                }
                val budget = aiGateway.checkBudget(uid, estTokens)
                if (budget is com.maodouchat.server.service.BudgetResult.Exceeded) {
                    call.response.header(HttpHeaders.RetryAfter, budget.retryAfterSeconds.toString())
                    aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "budget_exceeded", file.byteCount, durationMs = System.currentTimeMillis() - startedAt, error = "budget_exceeded")
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("AI 用量已达每日上限", code = "AI_BUDGET_EXCEEDED"))
                    return@post
                }
                when (val result = aiGateway.analyzeFile(file.base64, file.fileName, file.mimeType, request.mode, request.question)) {
                    is AiGatewayResult.Success -> {
                        aiRepo.recordAudit(uid, request.chatId, "file_analyze", result.model, "success", file.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, inputTokens = result.inputTokens, outputTokens = result.outputTokens)
                        call.respond(AiFileAnalyzeResponse(result.value.take(8_000), request.mode, file.fileName, result.model))
                    }
                    AiGatewayResult.NotConfigured -> {
                        aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "not_configured", file.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt)
                        call.respond(HttpStatusCode.ServiceUnavailable, ErrorResponse("AI 服务未配置"))
                    }
                    is AiGatewayResult.UpstreamError -> {
                        aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "upstream_error", file.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, error = result.message)
                        if (result.retryAfterSeconds != null) {
                            call.response.header(HttpHeaders.RetryAfter, result.retryAfterSeconds.toString())
                        }
                        call.respond(HttpStatusCode.BadGateway, ErrorResponse("AI 服务暂时不可用，请稍后重试"))
                    }
                    is AiGatewayResult.InvalidResponse -> {
                        aiRepo.recordAudit(uid, request.chatId, "file_analyze", null, "invalid_response", file.byteCount, 1, durationMs = System.currentTimeMillis() - startedAt, error = result.message)
                        call.respond(HttpStatusCode.BadGateway, ErrorResponse(result.message))
                    }
                }
            }

            // 星标消息
            post("/api/messages/{messageId}/star") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!com.maodouchat.server.service.RuntimeConfigService.isMessageStarringEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("starring_disabled"))
                    return@post
                }
                val mid = call.parameters["messageId"]!!
                val msg = messageRepo.getMessageById(mid)
                if (msg == null) { call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在")); return@post }
                if (!chatRepo.isParticipant(msg.chatId, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@post }
                val starred = starMessageRepo.toggleStar(uid, mid)
                if (starred == null) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("该消息不能星标"))
                    return@post
                }
                call.respond(buildJsonObject { put("status", "ok"); put("starred", starred) })
            }

            // 会话消息置顶（群：管理员；单聊：双方）
            get("/api/chats/{chatId}/pins") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val chatId = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(chatId, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作"))
                    return@get
                }
                call.respond(
                    PinnedMessagesListResponse(
                        chatId = chatId,
                        pins = pinnedMessageRepo.list(chatId)
                    )
                )
            }
            post("/api/chats/{chatId}/messages/{messageId}/pin") {
                if (call.rejectIfMaintenance()) return@post
                if (!RuntimeConfigService.isMessagePinEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("message_pin_disabled"))
                    return@post
                }
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfSuspended(userRepo, uid)) return@post
                val chatId = call.parameters["chatId"]!!
                val mid = call.parameters["messageId"]!!
                if (!chatRepo.isParticipant(chatId, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作"))
                    return@post
                }
                val chat = chatRepo.getChatById(chatId)
                if (chat == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("聊天不存在"))
                    return@post
                }
                val actorIsManager = if (chat.isGroup) chatRepo.isOwnerOrAdmin(chatId, uid) else true
                val outcome = pinnedMessageRepo.toggle(
                    chatId = chatId,
                    messageId = mid,
                    actorId = uid,
                    actorIsManager = actorIsManager
                )
                when (outcome.result) {
                    PinnedMessageRepository.PinResult.NOT_FOUND -> {
                        call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在"))
                        return@post
                    }
                    PinnedMessageRepository.PinResult.FORBIDDEN -> {
                        call.respond(HttpStatusCode.Forbidden, ErrorResponse("仅群主或管理员可置顶"))
                        return@post
                    }
                    PinnedMessageRepository.PinResult.LIMIT -> {
                        call.respond(
                            HttpStatusCode.BadRequest,
                            ErrorResponse("最多置顶 ${PinnedMessageRepository.MAX_PINS_PER_CHAT} 条消息")
                        )
                        return@post
                    }
                    PinnedMessageRepository.PinResult.NOT_PINNABLE -> {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("该消息不能置顶"))
                        return@post
                    }
                    PinnedMessageRepository.PinResult.PINNED,
                    PinnedMessageRepository.PinResult.UNPINNED -> {
                        val pinned = outcome.result == PinnedMessageRepository.PinResult.PINNED
                        val payload = PinnedMessagesUpdatedPayload(chatId, uid, outcome.pins)
                        val pinJson = json.encodeToString(
                            WsMessage.serializer(),
                            WsMessage(
                                "PINNED_MESSAGES_UPDATED",
                                json.encodeToString(PinnedMessagesUpdatedPayload.serializer(), payload)
                            )
                        )
                        chatRepo.getParticipantIds(chatId).forEach { participantId ->
                            sendToUser(participantId, pinJson)
                        }
                        call.respond(
                            TogglePinResponse(
                                status = "ok",
                                pinned = pinned,
                                pins = outcome.pins
                            )
                        )
                    }
                }
            }
            put("/api/messages/{messageId}/reaction") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfMessageRestricted(userRepo, uid)) return@put
                // 每用户限流：每次回应向全群成员 WS fanout，防帧风暴
                if (!reactionRateLimiter.acquire(uid, maxPerMinute = 60)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作太频繁，请稍后再试")); return@put
                }
                val mid = call.parameters["messageId"]!!
                val req = call.receiveBoundedText()?.let { parseJson<UpdateMessageReactionRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val emoji = req.emoji.trim()
                if (emoji !in ALLOWED_REACTION_EMOJIS) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("暂不支持该表情回应")); return@put
                }
                val msg = messageRepo.getMessageById(mid)
                if (msg == null) { call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在")); return@put }
                if (!chatRepo.isParticipant(msg.chatId, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@put }
                if (chatRepo.getChatById(msg.chatId)?.isGroup == true && chatRepo.isMuted(msg.chatId, uid)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法回应消息"))
                    return@put
                }
                if (!com.maodouchat.server.service.RuntimeConfigService.isReactionsEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("reactions_disabled"))
                    return@put
                }
                if (messageRepo.setReaction(mid, uid, emoji) == null) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("该消息不能回应"))
                    return@put
                }
                val actorReactions = messageRepo.getReactionsForViewer(mid, uid)
                // 双向拉黑过滤，与 NEW_MESSAGE fanout 口径一致
                val participants = chatRepo.getParticipantIds(msg.chatId)
                val blockedIds = try {
                    userRepo.blockedEitherWayIdsInTx(uid, participants)
                } catch (_: Exception) { emptySet() }
                val reactionViewers = participants.filter { it != uid && it !in blockedIds }
                val reactionsByViewer = messageRepo.getReactionsForViewers(mid, reactionViewers)
                reactionViewers.forEach { participantId ->
                    reactionsByViewer[participantId]?.let { viewerReactions ->
                        val viewerPayload = MessageReactionUpdatedPayload(msg.chatId, mid, uid, viewerReactions)
                        sendToUser(
                            participantId,
                            json.encodeToString(
                                WsMessage.serializer(),
                                WsMessage(
                                    "MESSAGE_REACTION_UPDATED",
                                    json.encodeToString(MessageReactionUpdatedPayload.serializer(), viewerPayload)
                                )
                            )
                        )
                    }
                }
                call.respond(MessageReactionUpdatedPayload(msg.chatId, mid, uid, actorReactions))
            }
            get("/api/messages/starred") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!com.maodouchat.server.service.RuntimeConfigService.isMessageStarringEnabled()) {
                    call.respond(emptyList<com.maodouchat.server.model.MessageResponse>())
                    return@get
                }
                val chatId = call.request.queryParameters["chatId"]
                call.respond(starMessageRepo.getStarredMessages(uid, chatId))
            }

            // 已读回执查询
            get("/api/messages/{messageId}/read-receipts") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                if (!com.maodouchat.server.service.RuntimeConfigService.isReadReceiptsEnabled()) {
                    call.respond(emptyList<com.maodouchat.server.model.ReadReceiptResponse>())
                    return@get
                }
                val mid = call.parameters["messageId"]!!
                val msg = messageRepo.getMessageById(mid)
                if (msg == null) { call.respond(HttpStatusCode.NotFound, ErrorResponse("消息不存在")); return@get }
                if (!chatRepo.isParticipant(msg.chatId, uid)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作")); return@get }
                call.respond(messageRepo.getReadReceipts(mid, uid))
            }

            // 批量标记聊天已读（一次请求标记多个聊天中所有未读消息为已读）
            post("/api/messages/batch-read") {
                val uid = call.principal<JWTPrincipal>()!!.payload.subject
                val req = call.receiveBoundedText()?.let { parseJson<BatchReadRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("请求体无效"))
                    return@post
                }
                if (req.chatIds.isEmpty() || req.chatIds.size > 50) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("聊天 ID 数量无效"))
                    return@post
                }
                val allUpdated = mutableMapOf<String, Int>()
                req.chatIds.forEach { chatId ->
                    if (chatRepo.isParticipant(chatId, uid)) {
                        val updated = messageRepo.markAllAsRead(chatId, uid)
                        if (updated.isNotEmpty()) {
                            allUpdated[chatId] = updated.size
                            // 群聊不推 MESSAGE_STATUS READ，避免一人已读=发送方全员已读
                            val isGroup = chatRepo.getChatById(chatId)?.isGroup == true
                            if (!isGroup) {
                                // 8.48 修复 M5：getParticipantIds 提到消息循环外（此前每条已读消息查一次）
                                val expireRecipients = try { chatRepo.getParticipantIds(chatId) } catch (_: Exception) { emptyList() }
                                updated.forEach { (messageId, senderId, expiresAt) ->
                                    // markAllAsRead 已过滤双向拉黑发送方
                                    val statusJson = json.encodeToString(
                                        WsMessage.serializer(),
                                        WsMessage("MESSAGE_STATUS", json.encodeToString(
                                            StatusUpdatePayload.serializer(),
                                            StatusUpdatePayload(messageId, "READ")
                                        ))
                                   )
                                   sendToUser(senderId, statusJson)
                                   if (expiresAt != null && expiresAt > 0L) {
                                   val expiresJson = json.encodeToString(
                                            WsMessage.serializer(),
                                            WsMessage(
                                                "MESSAGE_EXPIRES",
                                                json.encodeToString(
                                                    MessageExpiresPayload.serializer(),
                                                    MessageExpiresPayload(messageId, chatId, expiresAt)
                                                )
                                            )
                                        )
                                        expireRecipients.forEach { pid ->
                                            sendToUser(pid, expiresJson)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
put("updatedChats", allUpdated.size)
                }
            )
            }

            // 删除消息（仅发送者可删除，会通知聊天中的其他参与者）
            delete("/api/messages/{messageId}") {

                if (!RuntimeConfigService.isMessageRevokeEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("message_revoke_disabled"))
                    return@delete
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfMessageRestricted(userRepo, userId)) return@delete
                // 8.40：编辑/撤回/删除共享 mutation 限流
                if (!messageMutateRateLimiter.acquire(userId, maxPerMinute = 60)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@delete
                }
                val messageId = call.parameters["messageId"]!!
                val message = messageRepo.getMessageById(messageId)
                if (message == null) {
                    // 幂等：已删除视为成功，避免多设备/重试把 UI 回滚回来
                    call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    return@delete
                }
                if (!chatRepo.isParticipant(message.chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权操作该消息"))
                    return@delete
                }
                if (chatRepo.getChatById(message.chatId)?.isGroup == true && chatRepo.isMuted(message.chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("你已被禁言，暂时无法删除消息"))
                    return@delete
                }
                val deleteResult = messageRepo.deleteMessage(messageId, userId)
                when (deleteResult.ok) {
                    null -> {
                        call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                        return@delete
                    }
                    false -> {
                        call.respond(HttpStatusCode.Forbidden, ErrorResponse("只能删除自己发送的消息"))
                        return@delete
                    }
                    true -> Unit
                }
                // 附件行已在 delete 事务内删掉；这里只清磁盘
                deleteResult.deletedAttachmentIds.forEach(EncryptedAttachmentStorage::delete)
                // 通过 WebSocket 通知聊天中的其他参与者（与 NEW_MESSAGE 一致：双向拉黑均不推）
                val deleteNotification = json.encodeToString(
                    WsMessage.serializer(),
                    WsMessage("MESSAGE_DELETED", json.encodeToString(
                        DeleteMessagePayload.serializer(),
                        DeleteMessagePayload(messageId, message.chatId)
                    ))
                )
                val participants = chatRepo.getParticipantIds(message.chatId)
                val blockedIds = try {
                    userRepo.blockedEitherWayIdsInTx(userId, participants)
                } catch (_: Exception) { emptySet() }
                participants.forEach { participantId ->
                    if (participantId != userId && participantId !in blockedIds) {
                        sendToUser(participantId, deleteNotification)
                    }
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            // 多设备变更回放：DELETE/REVOKE/EDIT（离线设备靠此收敛，不依赖在线 WS）
            get("/api/chats/{chatId}/message-mutations") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val chatId = call.parameters["chatId"]!!
                if (!chatRepo.isParticipant(chatId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该聊天变更"))
                    return@get
                }
                val since = call.request.queryParameters["since"]?.toLongOrNull() ?: 0L
                val sinceId = call.request.queryParameters["sinceId"]
                    ?.takeIf { it.isNotBlank() && it.length <= 100 }
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 200).coerceIn(1, 500)
                call.respond(messageRepo.getMutationsSince(chatId, since, limit, sinceId, viewerId = userId))
            }
            // 发现页 / 动态 API
            get("/api/posts") {

                if (!RuntimeConfigService.isPostsEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("posts_disabled"))
                    return@get
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 30).coerceIn(1, 50)
                val before = call.request.queryParameters["before"]?.toLongOrNull()
                val beforeId = call.request.queryParameters["beforeId"]
                    ?.takeIf { before != null && it.isNotBlank() && it.length <= 100 }
                val authorId = call.request.queryParameters["authorId"]
                if (authorId != null) {
                    call.respond(postRepo.getPostsByAuthor(userId, authorId, limit, before, beforeId))
                } else {
                    call.respond(postRepo.getFeed(userId, limit, before, beforeId))
                }
            }

            post("/api/posts") {

                if (!RuntimeConfigService.isPostsEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("posts_disabled"))
                    return@post
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfPostRestricted(userRepo, userId)) return@post
                if (!postRateLimiter.acquire(userId, maxPerMinute = 20)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("发布过于频繁，请稍后再试"))
                    return@post
                }
                val req = call.receiveBoundedText()?.let { parseJson<CreatePostRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态内容无效"))
                    return@post
                }
                // Legacy clients always sent PUBLIC even when it only represented the UI default.
                // Preserve explicit CONTACTS/PRIVATE choices while failing closed for legacy PUBLIC.
                val useAccountDefault = req.useDefaultVisibility
                    ?: (req.visibility == null || req.visibility == "PUBLIC")
                val visibility = if (useAccountDefault) {
                    userRepo.getPrivacy(userId)?.defaultPostVisibility ?: "PRIVATE"
                } else {
                    req.visibility ?: run {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态可见性无效"))
                        return@post
                    }
                }
                if (!isValidPostPayload(req.content, req.imageUrls, visibility)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态内容无效"))
                    return@post
                }
                if (req.imageUrls.any { url ->
                        !com.maodouchat.server.service.FileStorageService.isOwnedPostImageUrl(url, userId)
                    }
                ) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态图片无效或不属于当前账号"))
                    return@post
                }
                val moderation = moderationRuleRepo.evaluate(
                    userId = userId,
                    source = "POST",
                    content = buildString {
                        append(req.content.trim())
                        if (req.imageUrls.isNotEmpty()) append('\n').append(req.imageUrls.joinToString("\n"))
                    }
                )
                if (moderation.blocked) {
                    val status = if (moderation.action == "AUTO_RATE_LIMIT") HttpStatusCode.TooManyRequests else HttpStatusCode.UnprocessableEntity
                    call.respond(status, ErrorResponse(moderation.message ?: "内容未通过安全检查"))
                    return@post
                }
                val created = try {
                    postRepo.createPost(userId, req.content.trim(), req.imageUrls, visibility)
                } catch (error: IllegalArgumentException) {
                    call.respond(HttpStatusCode.Conflict, ErrorResponse(error.message ?: "动态图片已被使用"))
                    return@post
                }
                call.respond(HttpStatusCode.Created, created)
            }

            post("/api/posts/images") {

                if (!RuntimeConfigService.isPostsEnabled()) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("posts_disabled"))
                    return@post
                }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfPostRestricted(userRepo, userId)) return@post
                if (!postImageRateLimiter.acquire(userId, maxPerMinute = 10)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("图片上传过于频繁，请稍后再试"))
                    return@post
                }
                val req = call.receiveBoundedText(MAX_UPLOAD_JSON_BODY_CHARS)?.let { parseJson<UploadPostImageRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                val imageUrl = try {
                    com.maodouchat.server.service.FileStorageService.savePostImage(req.base64Data, userId)
                } catch (e: IllegalArgumentException) {
                    // 不把内部校验明细回传给客户端，仅服务端日志保留上下文
                    call.application.log.warn("Post image upload rejected for user {}: {}", userId, e.message)
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("图片数据无效"))
                    return@post
                }
                call.respond(UploadPostImageResponse("ok", imageUrl))
            }

            delete("/api/posts/images/{filename}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val filename = call.parameters["filename"].orEmpty()
                if (!com.maodouchat.server.service.FileStorageService.isOwnedPostImageFilename(filename, userId)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态图片无效"))
                    return@delete
                }
                postRepo.deleteUnclaimedPostImage(filename, userId)
                call.respond(HttpStatusCode.NoContent)
            }

            get("/api/posts/{id}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                val post = postRepo.getPostById(postId, userId)
                if (post == null) call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                else call.respond(post)
            }

            delete("/api/posts/{id}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                if (!postRepo.exists(postId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                    return@delete
                }
                if (!postRepo.isAuthor(postId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权删除该动态"))
                    return@delete
                }
                postRepo.deletePost(postId, userId)
                broadcastPostDeleted(postId, actorId = userId)
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            put("/api/posts/{id}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                if (!postRepo.exists(postId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                    return@put
                }
                if (!postRepo.isAuthor(postId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权编辑该动态"))
                    return@put
                }
                val req = call.receiveBoundedText()?.let { parseJson<EditPostRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("请求体无效"))
                    return@put
                }
                val newContent = req.content.trim()
                if (newContent.isEmpty()) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态内容不能为空"))
                    return@put
                }
                if (newContent.length > MAX_POST_CONTENT_LENGTH) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("动态内容超出长度限制"))
                    return@put
                }
                if (req.visibility != null && !isValidPostVisibility(req.visibility)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("可见范围无效"))
                    return@put
                }
                // 8.38：编辑动态同样过内容审核（发动态/评论均过，编辑此前绕过——
                // 已发布内容可借编辑改成触发规则的内容）
                val moderation = moderationRuleRepo.evaluate(
                    userId = userId,
                    source = "POST",
                    content = newContent
                )
                if (moderation.blocked) {
                    val status = if (moderation.action == "AUTO_RATE_LIMIT") HttpStatusCode.TooManyRequests else HttpStatusCode.UnprocessableEntity
                    call.respond(status, ErrorResponse(moderation.message ?: "内容未通过安全检查"))
                    return@put
                }
                val updated = postRepo.updatePost(postId, userId, newContent, req.visibility)
                if (updated == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在或更新失败"))
                    return@put
                }
                call.respond(updated)
            }

            post("/api/posts/{id}/like") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfSuspended(userRepo, userId)) return@post
                val postId = call.parameters["id"]!!
                // 8.38：点赞/取消点赞限流——此前无限流可对作者反复 like/unlike 刷 FCM 通知
                if (!postLikeRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@post
                }
                // 1.137：禁止给自己的动态点赞
                if (postRepo.getPostAuthorId(postId) == userId) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能给自己的动态点赞"))
                    return@post
                }
                val wasAlreadyLiked = postRepo.hasLiked(postId, userId)
                if (!postRepo.likePost(postId, userId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                    return@post
                }
                val post = postRepo.getPostById(postId, userId)
                postRepo.getPostAuthorId(postId)?.let { authorId ->
                    if (!wasAlreadyLiked && !userRepo.isBlockedEitherWay(authorId, userId)) {
                        pushService.enqueuePostInteraction(authorId, userId, postId, "LIKE")
                    }
                }
                if (post != null) call.respond(post) else call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            delete("/api/posts/{id}/like") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                if (!postLikeRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@delete
                }
                if (!postRepo.unlikePost(postId, userId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                    return@delete
                }
                val post = postRepo.getPostById(postId, userId)
                if (post != null) call.respond(post) else call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            get("/api/posts/{id}/comments") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 50).coerceIn(1, 100)
                val before = call.request.queryParameters["before"]?.toLongOrNull()
                val beforeId = call.request.queryParameters["beforeId"]
                    ?.takeIf { before != null && it.isNotBlank() && it.length <= 100 }
                val comments = postRepo.getComments(postId, userId, limit, before, beforeId)
                if (comments == null) call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                else call.respond(comments)
            }

            // 1.93：动态点赞者列表
            get("/api/posts/{id}/likers") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = call.parameters["id"]!!
                val limit = (call.request.queryParameters["limit"]?.toIntOrNull() ?: 50).coerceIn(1, 100)
                val likers = postRepo.listPostLikers(postId, userId, limit)
                if (likers == null) call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在"))
                else call.respond(PostLikersResponse(postId, likers))
            }

            post("/api/posts/{id}/comments") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfPostRestricted(userRepo, userId)) return@post
                if (!commentRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("评论过于频繁，请稍后再试"))
                    return@post
                }
                val postId = call.parameters["id"]!!
                val req = call.receiveBoundedText()?.let { parseJson<CreateCommentRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                if (!isValidCommentPayload(req.content)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("评论内容无效"))
                    return@post
                }
                val moderation = moderationRuleRepo.evaluate(userId, "COMMENT", req.content.trim())
                if (moderation.blocked) {
                    val status = if (moderation.action == "AUTO_RATE_LIMIT") HttpStatusCode.TooManyRequests else HttpStatusCode.UnprocessableEntity
                    call.respond(status, ErrorResponse(moderation.message ?: "评论未通过安全检查"))
                    return@post
                }
                val comment = postRepo.addComment(postId, userId, req.content.trim(), req.replyToId)
                if (comment == null) call.respond(HttpStatusCode.NotFound, ErrorResponse("动态不存在或回复目标不存在"))
                else {
                    val postAuthorId = postRepo.getPostAuthorId(postId)
                    postAuthorId?.let { authorId ->
                        if (!userRepo.isBlockedEitherWay(authorId, userId)) {
                            // 1.130：评论附内容预览；1.132：附评论 id
                            pushService.enqueuePostInteraction(authorId, userId, postId, "COMMENT", comment.content, comment.id)
                        }
                    }
                    // 1.80：回复目标作者也通知（非发帖者本人时，避免重复）；1.122：互动类型细化 REPLY
                    val replyToId = req.replyToId
                    if (!replyToId.isNullOrBlank()) {
                        val replyAuthor = postRepo.getCommentAuthorId(replyToId)
                        if (replyAuthor != null && replyAuthor != postAuthorId && !userRepo.isBlockedEitherWay(replyAuthor, userId)) {
                            pushService.enqueuePostInteraction(replyAuthor, userId, postId, "REPLY", comment.content, comment.id)
                        }
                    }
                    call.respond(HttpStatusCode.Created, comment)
                }
            }

            put("/api/posts/{id}/comments/{cid}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfPostRestricted(userRepo, userId)) return@put
                if (!commentRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("评论操作过于频繁，请稍后再试"))
                    return@put
                }
                val postId = call.parameters["id"]!!
                val cid = call.parameters["cid"]!!
                val req = call.receiveBoundedText()?.let { parseJson<UpdateCommentRequest>(it) }
                if (req == null || !isValidCommentPayload(req.content)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("评论内容无效"))
                    return@put
                }
                val moderation = moderationRuleRepo.evaluate(userId, "COMMENT", req.content.trim())
                if (moderation.blocked) {
                    val status = if (moderation.action == "AUTO_RATE_LIMIT") HttpStatusCode.TooManyRequests else HttpStatusCode.UnprocessableEntity
                    call.respond(status, ErrorResponse(moderation.message ?: "评论未通过安全检查"))
                    return@put
                }
                val comment = postRepo.updateCommentForUser(cid, postId, userId, req.content.trim())
                if (comment == null) call.respond(HttpStatusCode.NotFound, ErrorResponse("评论不存在或无权编辑"))
                else call.respond(comment)
            }

            delete("/api/posts/{id}/comments/{cid}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["cid"]!!
                val ok = postRepo.deleteCommentForUser(cid, userId)
                if (ok) call.respond(
                buildJsonObject {
put("status", "deleted")
                }
            )
                else call.respond(HttpStatusCode.NotFound, ErrorResponse("评论不存在或无权删除"))
            }

            // 1.52：评论点赞/取消点赞（1.83：独立限流与动态点赞隔离）
            post("/api/posts/{id}/comments/{cid}/like") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfPostRestricted(userRepo, userId)) return@post
                val cid = call.parameters["cid"]!!
                if (!commentLikeRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@post
                }
                val (likeCount, newLike) = postRepo.likeComment(cid, userId)
                if (likeCount < 0) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("评论不存在"))
                    return@post
                }
                // 1.87：新点赞时通知评论作者（非本人、双向拉黑过滤）；1.113：互动类型细化 COMMENT_LIKE
                if (newLike) {
                    val commentAuthor = postRepo.getCommentAuthorId(cid)
                    if (commentAuthor != null && commentAuthor != userId && !userRepo.isBlockedEitherWay(commentAuthor, userId)) {
                        // 1.130：评论被赞附内容预览；1.132：附评论 id
                        val preview = postRepo.getComment(cid, userId)?.content
                        pushService.enqueuePostInteraction(commentAuthor, userId, call.parameters["id"]!!, "COMMENT_LIKE", preview, cid)
                    }
                }
                call.respond(
                buildJsonObject {
put("status", "liked")
put("likeCount", likeCount)
                }
            )
            }
            delete("/api/posts/{id}/comments/{cid}/like") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val cid = call.parameters["cid"]!!
                if (!commentLikeRateLimiter.acquire(userId, maxPerMinute = 30)) {
                    call.respond(HttpStatusCode.TooManyRequests, ErrorResponse("操作过于频繁，请稍后再试"))
                    return@delete
                }
                val likeCount = postRepo.unlikeComment(cid, userId)
                call.respond(
                buildJsonObject {
put("status", "unliked")
put("likeCount", likeCount)
                }
            )
            }

            // ─── 上传文件访问 API ────────────────
            // 必须经过 JWT 认证 — 旧 staticFiles("/uploads") 已被移除，避免 visibility 旁路
            // 头像：任何登录用户都可获取（头像本身是公开信息）
            get("/api/files/avatar/{filename}") {
                val filename = call.parameters["filename"]!!
                if (!filename.matches(Regex("^[A-Za-z0-9_.-]+$"))) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("文件名无效")); return@get }
                val avatarUrl = com.maodouchat.server.service.FileStorageService.avatarUrl(filename)
                if (avatarUrl == null || !userRepo.isCurrentAvatarUrl(avatarUrl)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("文件不存在"))
                    return@get
                }
                val file = com.maodouchat.server.service.FileStorageService.resolveFile("avatars", filename)
                if (file == null || !file.exists()) { call.respond(HttpStatusCode.NotFound, ErrorResponse("文件不存在")); return@get }
                call.respondFile(file)
            }
            get("/api/chats/{chatId}/avatar/file/{filename}") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val chatId = call.parameters["chatId"]!!
                val filename = call.parameters["filename"]!!
                if (!filename.matches(Regex("^[A-Za-z0-9_.-]+$"))) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("文件名无效")); return@get }
                val chat = chatRepo.getChatById(chatId)
                if (chat == null || !chatRepo.isParticipant(chatId, userId)) { call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问群头像")); return@get }
                if (com.maodouchat.server.service.FileStorageService.groupAvatarFilename(chat.groupAvatar, chatId) != filename) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("群头像不存在")); return@get
                }
                val file = com.maodouchat.server.service.FileStorageService.resolveFile("group-avatars", filename)
                if (file == null || !file.exists()) { call.respond(HttpStatusCode.NotFound, ErrorResponse("文件不存在")); return@get }
                call.respondFile(file)
            }
            // 动态图片：通过 filename→postId 映射查找对应动态，再校验可见性
            get("/api/files/post-image/{filename}") {
                val filename = call.parameters["filename"]!!
                if (!filename.matches(Regex("^[A-Za-z0-9_.-]+$"))) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("文件名无效")); return@get }
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val postId = postRepo.findPostIdByImageFilename(filename)
                if (postId == null) { call.respond(HttpStatusCode.NotFound, ErrorResponse("文件不存在")); return@get }
                if (!postRepo.canView(postId, userId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无权访问该动态图片"))
                    return@get
                }
                val file = com.maodouchat.server.service.FileStorageService.resolveFile("posts", filename)
                if (file == null || !file.exists()) { call.respond(HttpStatusCode.NotFound, ErrorResponse("文件不存在")); return@get }
                call.respondFile(file)
            }

            // ─── Signal 密钥交换 API ──────────
            // 上传密钥包（注册/初始化时调用）
            post("/api/keys/upload") {
                val principal = call.principal<JWTPrincipal>()!!
                val userId = principal.payload.subject
                val authSessionId = JwtConfig.authSessionId(principal.payload)!!
                val req = call.receiveBoundedText()?.let { parseJson<UploadKeysRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                if (!req.isValid()) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("密钥包无效"))
                    return@post
                }

                // Single transaction: SPK + signature + identity never partially published
                val uploadResult = signalKeyRepo.uploadKeyPackage(
                    userId = userId,
                    authSessionId = authSessionId,
                    deviceId = req.deviceId,
                    identityKey = req.identityKey,
                    registrationId = req.registrationId,
                    signedPreKeyId = req.signedPreKeyId,
                    signedPreKey = req.signedPreKey,
                    signedPreKeySignature = req.signedPreKeySignature,
                    preKeys = req.preKeys.map { SignalKeyRepository.PreKeyUpload(it.keyId, it.publicKey) },
                    deviceName = req.deviceName,
                )
                when (uploadResult) {
                    SignalKeyRepository.UploadKeyPackageResult.UPLOADED -> Unit
                    SignalKeyRepository.UploadKeyPackageResult.DEVICE_ID_CONFLICT -> {
                        call.respond(
                            HttpStatusCode.Conflict,
                            ErrorResponse("设备编号冲突，请重新分配设备编号", code = "DEVICE_ID_CONFLICT")
                        )
                        return@post
                    }
                    SignalKeyRepository.UploadKeyPackageResult.SESSION_CONFLICT -> {
                        call.respond(
                            HttpStatusCode.Conflict,
                            ErrorResponse("设备会话冲突，请重新登录", code = "DEVICE_SESSION_CONFLICT")
                        )
                        return@post
                    }
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            // 获取目标用户的 PreKeyBundle（兼容主设备接口）
            get("/api/keys/{userId}/prekey-bundle") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val targetUserId = call.parameters["userId"]!!
                if (!call.canFetchKeys(requesterId, targetUserId, chatRepo, preKeyFetchTracker)) return@get
                // 仅已确认设备；禁止默认 deviceId=1 消费未确认/幽灵设备的 one-time prekey
                val deviceId = signalKeyRepo.getDeviceIds(targetUserId, confirmedOnly = true).firstOrNull()
                if (deviceId == null || !signalKeyRepo.isDeviceConfirmed(targetUserId, deviceId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("用户密钥未上传或设备未确认"))
                    return@get
                }
                val bundle = signalKeyRepo.getBundle(targetUserId, deviceId)
                if (bundle == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("用户密钥未上传"))
                    return@get
                }
                call.respond(bundle.toPreKeyBundleResponse())
            }

            get("/api/keys/{userId}/devices") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val targetUserId = call.parameters["userId"]!!
                if (!call.canFetchKeys(requesterId, targetUserId, chatRepo, preKeyFetchTracker, allowSelf = true)) return@get
                val currentDeviceId = call.request.queryParameters["currentDeviceId"]?.toIntOrNull()
                call.respond(signalKeyRepo.getDeviceInfos(targetUserId, currentDeviceId, includePending = requesterId == targetUserId).map {
                    DeviceInfoResponse(
                        userId = it.userId,
                        deviceId = it.deviceId,
                        deviceName = it.deviceName,
                        identityKey = it.identityKey,
                        lastSeenAt = it.lastSeenAt,
                        isCurrent = it.isCurrent,
                        status = it.status,
                        confirmedAt = it.confirmedAt,
                        confirmedByDeviceId = it.confirmedByDeviceId
                    )
                })
            }

            put("/api/keys/devices/{deviceId}/name") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val deviceId = call.parameters["deviceId"]?.toIntOrNull()
                if (deviceId == null || deviceId !in 1..255) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备 ID 无效"))
                    return@put
                }
                val req = call.receiveBoundedText()?.let { parseJson<UpdateDeviceNameRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@put
                }
                val name = req.deviceName.trim()
                if (name.isBlank() || name.length > 50) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备名长度需 1-50 字符"))
                    return@put
                }
                if (!signalKeyRepo.updateDeviceName(requesterId, deviceId, name)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("设备不存在"))
                    return@put
                }
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            post("/api/keys/devices/{deviceId}/confirm") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val deviceId = call.parameters["deviceId"]?.toIntOrNull()
                if (deviceId == null || deviceId !in 1..255) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备 ID 无效"))
                    return@post
                }
                val req = call.receiveBoundedText()?.let { parseJson<ConfirmDeviceRequest>(it) } ?: run {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post
                }
                when (signalKeyRepo.confirmDevice(requesterId, deviceId, req.approverDeviceId, req.signature)) {
                    SignalKeyRepository.ConfirmDeviceResult.CONFIRMED,
                    SignalKeyRepository.ConfirmDeviceResult.ALREADY_CONFIRMED -> call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    SignalKeyRepository.ConfirmDeviceResult.NOT_FOUND -> call.respond(HttpStatusCode.NotFound, ErrorResponse("设备不存在"))
                    SignalKeyRepository.ConfirmDeviceResult.APPROVER_NOT_TRUSTED -> call.respond(HttpStatusCode.Forbidden, ErrorResponse("请使用已确认的其他设备批准登录"))
                    SignalKeyRepository.ConfirmDeviceResult.INVALID_PROOF -> call.respond(HttpStatusCode.Forbidden, ErrorResponse("设备批准证明无效"))
                    SignalKeyRepository.ConfirmDeviceResult.INVALID -> call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备 ID 无效"))
                }
            }

            delete("/api/keys/devices/{deviceId}") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val deviceId = call.parameters["deviceId"]?.toIntOrNull()
                if (deviceId == null || deviceId !in 1..255) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备 ID 无效"))
                    return@delete
                }
                // 8.61：禁止删除「当前登录会话所在设备」——客户端本地 signalProtocol.getDeviceId()
                // 在库重建/换机迁移后可能与服务端不一致，误删当前设备会吊销自己登录（自锁）。
                // 服务端以 auth session 绑定的 deviceId 为权威判定。
                val authSessionId = JwtConfig.authSessionId(call.principal<JWTPrincipal>()!!.payload)
                if (authSessionId != null) {
                    val currentDeviceId = org.jetbrains.exposed.sql.transactions.transaction {
                        com.maodouchat.server.db.AuthSessions.selectAll()
                            .where { com.maodouchat.server.db.AuthSessions.id eq authSessionId }
                            .firstOrNull()
                            ?.get(com.maodouchat.server.db.AuthSessions.signalDeviceId)
                    }
                    if (currentDeviceId != null && currentDeviceId == deviceId) {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能移除当前登录设备"))
                        return@delete
                    }
                }
                val removal = signalKeyRepo.deleteDeviceAndRevokeSessionsGuarded(requesterId, deviceId)
                when (removal.result) {
                    SignalKeyRepository.DeleteDeviceResult.NOT_FOUND -> {
                        call.respond(HttpStatusCode.NotFound, ErrorResponse("设备不存在"))
                        return@delete
                    }
                    SignalKeyRepository.DeleteDeviceResult.LAST_CONFIRMED -> {
                        call.respond(HttpStatusCode.BadRequest, ErrorResponse("至少保留一个已确认设备"))
                        return@delete
                    }
                    SignalKeyRepository.DeleteDeviceResult.DELETED -> {
                        disconnectUserSessionsByAuthSessionIds(
                            requesterId,
                            removal.revokedSessionIds,
                            "该登录设备已被移除"
                        )
                        aiSummarySyncRepo.deleteForDevice(requesterId, deviceId)
                        call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
                    }
                }
            }

            get("/api/keys/{userId}/devices/{deviceId}/prekey-bundle") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val targetUserId = call.parameters["userId"]!!
                val deviceId = call.parameters["deviceId"]?.toIntOrNull()
                if (deviceId == null || deviceId !in 1..255) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("设备 ID 无效"))
                    return@get
                }
                if (!call.canFetchKeys(requesterId, targetUserId, chatRepo, preKeyFetchTracker)) return@get
                if (!signalKeyRepo.isDeviceConfirmed(targetUserId, deviceId)) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("设备尚未确认"))
                    return@get
                }
                val bundle = signalKeyRepo.getBundle(targetUserId, deviceId)
                if (bundle == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("设备密钥未上传"))
                    return@get
                }
                call.respond(bundle.toDevicePreKeyBundleResponse())
            }

            get("/api/keys/{userId}/prekey-bundles") {
                val requesterId = call.principal<JWTPrincipal>()!!.payload.subject
                val targetUserId = call.parameters["userId"]!!
                if (!call.canFetchKeys(requesterId, targetUserId, chatRepo, preKeyFetchTracker, allowSelf = true)) return@get
                // Discovery-only: SPK + identity, no OTPK peek. Real session setup must use
                // per-device prekey-bundle (consume). Prevents multi-sender OTPK reuse.
                val bundles = signalKeyRepo.getDeviceIds(targetUserId).mapNotNull {
                    signalKeyRepo.getBundle(targetUserId, it, consumeOneTimePreKey = false, includeOneTimePreKey = false)
                }
                if (bundles.isEmpty()) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("用户密钥未上传"))
                    return@get
                }
                call.respond(bundles.map { it.toDevicePreKeyBundleResponse() })
            }

            // ─── WebRTC 信令 API ─────────────
            get("/api/calls/ice-config") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                call.respond(turnCredentialService.issue(userId))
            }

            // 发送信令消息
            
            get("/api/e2ee/sealed-sender/certificate") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                if (!RuntimeConfigService.isSealedSenderEnabled()) {
                    call.respond(HttpStatusCode.ServiceUnavailable, ErrorResponse("sealed sender disabled"))
                    return@get
                }
                val deviceId = call.request.queryParameters["deviceId"]?.toIntOrNull() ?: 1
                val issued = SealedSenderCertificateService.issue(userId, deviceId)
                    ?: run {
                        call.respond(HttpStatusCode.InternalServerError, ErrorResponse("failed to issue certificate"))
                        return@get
                    }
                call.respond(
                buildJsonObject {
put("certificate", issued.certificate)
put("expiresAt", issued.expiresAt)
put("deviceId", issued.deviceId)
put("userId", issued.userId)
put("version", "v1")
                }
            )
            }

            post("/api/e2ee/sealed-sender/verify") {
                val body = call.receiveBoundedTextOrEmpty()
                val obj = runCatching { Json.parseToJsonElement(body).jsonObject }.getOrNull()
                val cert = obj?.get("certificate")?.jsonPrimitive?.content.orEmpty()
                val verified = SealedSenderCertificateService.verify(cert)
                if (verified == null) {
                    call.respond(
                buildJsonObject {
put("ok", false)
                }
            )
                } else {
                    call.respond(
                buildJsonObject {
put("ok", true)
put("userId", verified.userId)
put("deviceId", verified.deviceId)
put("expiresAt", verified.expiresAt)
                }
            )
                }
            }

post("/api/signaling/send") {
                val fromUserId = call.principal<JWTPrincipal>()!!.payload.subject
                if (call.rejectIfMessageRestricted(userRepo, fromUserId)) return@post
                val req = call.receiveBoundedText()?.let { parseJson<SendSignalRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                if (!isValidSignalPayload(req.type, req.payload) || !isValidCallId(req.callId)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("信令内容无效"))
                    return@post
                }
                if (req.toUserId == fromUserId) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能向自己发送信令"))
                    return@post
                }
                if (userRepo.getById(req.toUserId) == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("信令目标用户不存在"))
                    return@post
                }
                if (!isValidGroupSignalMetadata(req.groupId, req.groupMemberIds, req.groupInvite, req.callId, fromUserId, req.toUserId, chatRepo)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("群通话元数据无效"))
                    return@post
                }
                if (userRepo.isBlockedEitherWay(fromUserId, req.toUserId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无法与已屏蔽的用户发起通话"))
                    return@post
                }
                // 1:1 signaling requires an existing shared chat (group path validated separately)
                if (req.groupId.isBlank() && !chatRepo.shareChat(fromUserId, req.toUserId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("双方无共同会话，无法发起通话"))
                    return@post
                }
                if (CallInviteRateLimiter.isInitialInvite(req.type, req.groupId, req.groupInvite)) {
                    val key = CallInviteRateLimiter.sessionKey(req.callId, req.groupId, req.toUserId)
                    val decision = callInviteRateLimiter.tryAcquire(fromUserId, key)
                    if (!decision.allowed) {
                        call.response.headers.append(HttpHeaders.RetryAfter, decision.retryAfterSeconds.toString())
                        call.respond(
                            HttpStatusCode.TooManyRequests,
                            ErrorResponse("发起通话过于频繁，请稍后再试", "CALL_INVITE_RATE_LIMITED", decision.retryAfterSeconds)
                        )
                        return@post
                    }
                }

                // 与 WS 路径一致：终端信令与清理同事务，避免离线 offersOnly 仍响铃
                val terminalTypes = setOf("hang-up", "busy", "reject")
                if (req.type.lowercase() in terminalTypes) {
                    signalingRepo.storeTerminalAndClearOthers(
                        fromUserId, req.toUserId, req.type, req.payload,
                        req.callId, req.groupId, req.groupMemberIds, req.groupInvite
                    )
                } else {
                    signalingRepo.store(
                        fromUserId, req.toUserId, req.type, req.payload,
                        req.callId, req.groupId, req.groupMemberIds, req.groupInvite
                    )
                }

                // 如果目标用户在线，通过 WebSocket 实时推送
                sendToUser(req.toUserId, kotlinx.serialization.json.Json.encodeToString(
                    WsMessage.serializer(),
                    WsMessage("SIGNALING", kotlinx.serialization.json.Json.encodeToString(
                        SignalingPayload.serializer(),
                        SignalingPayload(fromUserId, req.type, req.payload, req.callId, req.groupId, req.groupMemberIds, req.groupInvite)
                    ))
                ))

                if (req.type.equals("offer", ignoreCase = true) && (req.groupId.isBlank() || req.groupInvite)) {
                    pushService.enqueueIncomingCall(
                        recipientId = req.toUserId,
                        senderId = fromUserId,
                        isVideo = sdpHasActiveVideo(req.payload),
                        callId = req.callId
                    )
                }

                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }

            // 获取待处理的信令消息（轮询模式，WebSocket 断开时使用）
            get("/api/signaling/pending") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val offersOnly = call.request.queryParameters["offersOnly"]?.toBooleanStrictOrNull() == true
                val messages = signalingRepo.consumeForUser(userId, offersOnly)
                call.respond(messages.map {
                    SignalMessageResponse(it.id, it.fromUserId, it.type, it.payload, it.timestamp, it.callId, it.groupId, it.groupMemberIds, it.groupInvite)
                })
            }

            // 挂断通话（清理信令消息）
            post("/api/signaling/hangup") {
                val userId = call.principal<JWTPrincipal>()!!.payload.subject
                val req = call.receiveBoundedText()?.let { parseJson<SendSignalRequest>(it) }
                if (req == null) { call.respond(HttpStatusCode.BadRequest, ErrorResponse("参数无效")); return@post }
                if (!isValidSignalPayload(req.type, req.payload) || !isValidCallId(req.callId)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("信令内容无效"))
                    return@post
                }
                if (req.toUserId == userId) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("不能向自己挂断通话"))
                    return@post
                }
                if (userRepo.getById(req.toUserId) == null) {
                    call.respond(HttpStatusCode.NotFound, ErrorResponse("目标用户不存在"))
                    return@post
                }
                if (!isValidGroupSignalMetadata(req.groupId, req.groupMemberIds, req.groupInvite, req.callId, userId, req.toUserId, chatRepo)) {
                    call.respond(HttpStatusCode.BadRequest, ErrorResponse("群通话元数据无效"))
                    return@post
                }
                if (userRepo.isBlockedEitherWay(userId, req.toUserId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("无法与已屏蔽的用户发送通话信令"))
                    return@post
                }
                if (req.groupId.isBlank() && !chatRepo.shareChat(userId, req.toUserId)) {
                    call.respond(HttpStatusCode.Forbidden, ErrorResponse("双方无共同会话，无法挂断通话"))
                    return@post
                }
                // hang-up + 清理旧信令同事务：崩溃也不会留下「有 hang-up 无清理」或「有清理无 hang-up」
                signalingRepo.storeTerminalAndClearOthers(
                    userId, req.toUserId, "hang-up", req.payload,
                    req.callId, req.groupId, req.groupMemberIds, req.groupInvite
                )
                sendToUser(req.toUserId, json.encodeToString(
                    WsMessage.serializer(),
                    WsMessage("SIGNALING", json.encodeToString(
                        SignalingPayload.serializer(),
                        SignalingPayload(userId, "hang-up", req.payload, req.callId, req.groupId, req.groupMemberIds, req.groupInvite)
                    ))
                ))
                call.respond(
                buildJsonObject {
put("status", "ok")
                }
            )
            }
        }
    }
}

private data class ValidatedAiImage(val base64: String, val mimeType: String, val byteCount: Int)

private fun validateAiImage(base64: String): ValidatedAiImage? = runCatching {
    val bytes = Base64.getDecoder().decode(base64.replace('-', '+').replace('_', '/'))
    if (bytes.isEmpty() || bytes.size > MAX_AI_IMAGE_BYTES) return null
    val imageInput = ImageIO.createImageInputStream(ByteArrayInputStream(bytes)) ?: return null
    imageInput.use { input ->
        val readers = ImageIO.getImageReaders(input)
        if (!readers.hasNext()) return null
        val reader = readers.next()
        try {
            reader.input = input
            val width = reader.getWidth(0)
            val height = reader.getHeight(0)
            if (width !in 1..MAX_AI_IMAGE_DIMENSION || height !in 1..MAX_AI_IMAGE_DIMENSION) return null
            if (width.toLong() * height.toLong() > MAX_AI_IMAGE_PIXELS) return null
            val mimeType = when (reader.formatName.lowercase()) {
                "jpg", "jpeg" -> "image/jpeg"
                "png" -> "image/png"
                else -> return null
            }
            // 8.52 修复 AI-3：超长边图片等比降采样到目标尺寸（视觉模型按像素/tile 计费，
            // 原图 4096² 成本是 1568² 的数倍，且游离在预算体系外）
            val maxEdge = maxOf(width, height)
            if (maxEdge > AI_IMAGE_TARGET_MAX_EDGE) {
                val sourceImage = reader.read(0) ?: return null
                val targetEdge = AI_IMAGE_TARGET_MAX_EDGE
                val scale = targetEdge.toDouble() / maxEdge
                val targetW = maxOf(1, (width * scale).toInt())
                val targetH = maxOf(1, (height * scale).toInt())
                val scaled = java.awt.image.BufferedImage(targetW, targetH, java.awt.image.BufferedImage.TYPE_INT_RGB)
                val graphics = scaled.createGraphics()
                graphics.drawImage(sourceImage, 0, 0, targetW, targetH, null)
                graphics.dispose()
                val bos = java.io.ByteArrayOutputStream()
                ImageIO.write(scaled, "jpg", bos)
                val outBytes = bos.toByteArray()
                return ValidatedAiImage(
                    Base64.getEncoder().encodeToString(outBytes),
                    "image/jpeg",
                    outBytes.size
                )
            }
            ValidatedAiImage(Base64.getEncoder().encodeToString(bytes), mimeType, bytes.size)
        } finally {
            reader.dispose()
        }
    }
}.getOrNull()

private data class ValidatedAiFile(
    val base64: String,
    val fileName: String,
    val mimeType: String,
    val byteCount: Int
)

private fun validateAiFile(base64: String, fileName: String, declaredMimeType: String): ValidatedAiFile? = runCatching {
    val bytes = Base64.getDecoder().decode(base64.replace('-', '+').replace('_', '/'))
    if (bytes.isEmpty() || bytes.size > MAX_AI_FILE_BYTES) return null
    val normalizedName = fileName.trim().take(120)
    val extension = normalizedName.substringAfterLast('.', "").lowercase()
    val isPdf = bytes.size >= 5 && bytes.copyOfRange(0, 5).contentEquals("%PDF-".toByteArray(Charsets.US_ASCII))
    val mimeType = if (isPdf) {
        if (extension != "pdf" || declaredMimeType.lowercase() != "application/pdf") return null
        "application/pdf"
    } else {
        if (declaredMimeType.lowercase() !in ALLOWED_AI_FILE_MIME_TYPES - "application/pdf") return null
        if (extension !in ALLOWED_AI_TEXT_FILE_EXTENSIONS) return null
        val text = Charsets.UTF_8.newDecoder()
            .onMalformedInput(CodingErrorAction.REPORT)
            .onUnmappableCharacter(CodingErrorAction.REPORT)
            .decode(ByteBuffer.wrap(bytes))
            .toString()
        if (text.isBlank() || text.length > MAX_AI_TEXT_FILE_CHARS || text.any { it == '\u0000' }) return null
        declaredMimeType.lowercase()
    }
    ValidatedAiFile(Base64.getEncoder().encodeToString(bytes), normalizedName, mimeType, bytes.size)
}.getOrNull()

